#ifndef __wasm__
#  define RUNTIME_ASSERT(cond)                                            \
    if (!(cond)) {                                                        \
      (void)fprintf(                                                      \
          stderr, "lex_nim: %s():%d: Assertion `%s' failed.\n", __func__, \
          __LINE__, #cond);                                               \
      abort();                                                            \
    }
#else
// WASM doesn't have printing enabled
#  define RUNTIME_ASSERT(cond) \
    if (!(cond)) {             \
      abort();                 \
    }
#endif

#define MIN(left, right) ((left) > (right) ? (right) : (left))
#define MAX(left, right) ((left) < (right) ? (right) : (left))

typedef uint8_t indent_value;
const indent_value INVALID_INDENT_VALUE = (indent_value)~0U;

struct indent_vec {
  int32_t len;
  int32_t capacity;
  indent_value* data;
};

#define INDENT_VEC_EMPTY                  \
  {                                       \
    .len = 0, .capacity = 0, .data = NULL \
  }

_nonnull_(1) static void indent_vec_destroy(struct indent_vec* self)
{
  ts_free(self->data);
  memset(self, 0, sizeof(*self));
}

_nonnull_(1) _returns_nonnull_ static indent_value* indent_vec_at(
    struct indent_vec* self, int32_t idx)
{
  RUNTIME_ASSERT(idx >= 0 && idx < self->len);
  return &self->data[idx];
}

_nonnull_(1) static indent_value indent_vec_get(
    const struct indent_vec* self, int32_t idx)
{
  return *indent_vec_at((struct indent_vec*)self, idx);
}

_nonnull_(1) _returns_nonnull_ static indent_value* indent_vec_at_capacity(
    struct indent_vec* self, int32_t idx)
{
  RUNTIME_ASSERT(idx >= 0 && idx < self->capacity);
  return &self->data[idx];
}

_nonnull_(1) static int indent_vec_set_capacity(
    struct indent_vec* self, int32_t size)
{
  if (size < 0) {
    return -1;
  }
  if (size != self->capacity) {
    indent_value* new_data = ts_realloc(self->data, size);
    if (!new_data) {
      return -1;
    }
    self->data = new_data;
    self->capacity = size;
    self->len = MIN(self->len, size);
    for (int i = self->len; i < size; i++) {
      *indent_vec_at_capacity(self, i) = INVALID_INDENT_VALUE;
    }
  }
  return 0;
}

_nonnull_(1) static int indent_vec_set_len(
    struct indent_vec* self, int32_t size)
{
  if (size < 0) {
    return -1;
  }
  if (size > self->capacity) {
    if (indent_vec_set_capacity(self, size) < 0) {
      return -1;
    }
  }

  for (int i = self->len; i < size; i++) {
    *indent_vec_at_capacity(self, i) = INVALID_INDENT_VALUE;
  }
  self->len = size;

  return 0;
}

_nonnull_(1) static int indent_vec_push(
    struct indent_vec* self, indent_value value)
{
  if (self->len >= self->capacity) {
    int32_t new_capacity = self->len >= 2 ? self->len * 3 / 2 : self->len + 1;
    if (indent_vec_set_capacity(self, new_capacity) < 0) {
      return -1;
    }
  }

  self->len++;
  *indent_vec_at(self, self->len - 1) = value;

  return 0;
}

_nonnull_(1) static void indent_vec_pop(struct indent_vec* self)
{
  indent_vec_set_len(self, MAX(0, self->len - 1));
}

_nonnull_(1) static indent_value indent_vec_back(const struct indent_vec* self)
{
  return indent_vec_get(self, self->len - 1);
}

_nonnull_(1, 2) static unsigned indent_vec_serialize(
    const struct indent_vec* self, char* buffer, unsigned buffer_len)
{
  size_t n_bytes = self->len * sizeof(*self->data);
  if (n_bytes > buffer_len) {
    DBG_F(
        "warning: buffer is smaller than vector (%u < %zd), partially "
        "serializing",
        buffer_len, n_bytes);
  }

  // Prevents passing NULL pointer to memcpy
  if (n_bytes == 0) {
    return n_bytes;
  }

  unsigned serialize_len = MIN(buffer_len, n_bytes);
  memcpy(buffer, self->data, n_bytes);
  return serialize_len;
}

_nonnull_(1, 2) static void indent_vec_deserialize(
    struct indent_vec* self, const char* buffer, unsigned buffer_len)
{
  int32_t n_items = (int32_t)MIN(buffer_len / sizeof(*self->data), INT32_MAX);
  if (indent_vec_set_len(self, n_items) < 0) {
    DBG("cannot deserialize: set_len failed");
    return;
  }
  if (n_items > 0) {
    memcpy(self->data, buffer, n_items * sizeof(*self->data));
  }
}

_nonnull_(1) static void indent_vec_debug(const struct indent_vec* self)
{
  if (debug_mode) {
    DBG_F("current layout stack: [");
    for (int32_t i = 0; i < self->len; i++) {
      (void)dprintf(" %" PRIu8, indent_vec_get(self, i));
    }
    (void)dprintf(" ]\n");
  }
}

enum token_type {
  TOKEN_TYPE_START,
  BLOCK_COMMENT_CONTENT = TOKEN_TYPE_START,
  BLOCK_DOC_COMMENT_CONTENT,
  COMMENT_CONTENT,
  LONG_STRING_QUOTE,
  LAYOUT_START,
  LAYOUT_END,
  LAYOUT_TERMINATOR,
  LAYOUT_EMPTY,
  INHIBIT_LAYOUT_END,
  INHIBIT_KEYWORD_TERMINATION,
  COMMA,
  SYNCHRONIZE,
  INVALID_LAYOUT,
  SIGIL_OP,
  UNARY_OP,
  WANT_EXPORT_MARKER,
  OF,
  TOKEN_TYPE_LEN
};

#ifdef TREE_SITTER_INTERNAL_BUILD
const char* const TOKEN_TYPE_STR[TOKEN_TYPE_LEN] = {
    "BLOCK_COMMENT_CONTENT",
    "BLOCK_DOC_COMMENT_CONTENT",
    "COMMENT_CONTENT",
    "LONG_STRING_QUOTE",
    "LAYOUT_START",
    "LAYOUT_END",
    "LAYOUT_TERMINATOR",
    "LAYOUT_EMPTY",
    "INHIBIT_LAYOUT_END",
    "INHIBIT_KEYWORD_TERMINATION",
    "COMMA",
    "SYNCHRONIZE",
    "INVALID_LAYOUT",
    "SIGIL_OP",
    "UNARY_OP",
    "WANT_EXPORT_MARKER",
    "OF",
};
#endif

struct valid_tokens {
  uint32_t bits : TOKEN_TYPE_LEN;
};

#define TO_VT_BIT(value) 1U << (enum token_type)(value)
#define VALID_TOKENS(bits_) \
  {                         \
    .bits = (bits_)         \
  }

_nonnull_(1) _pure_ static struct valid_tokens valid_tokens_from_array(
    const bool* valid_tokens)
{
  struct valid_tokens result = {0};
  for (unsigned i = TOKEN_TYPE_START; i < TOKEN_TYPE_LEN; i++) {
    result.bits |= (unsigned)valid_tokens[i] << i;
  }
  return result;
}

_const_ static bool valid_tokens_test(
    struct valid_tokens self, enum token_type type)
{
  return (self.bits & TO_VT_BIT(type)) != 0;
}

_const_ static bool valid_tokens_any_valid(
    struct valid_tokens left, struct valid_tokens right)
{
  return (left.bits & right.bits) != 0;
}

_const_ static bool valid_tokens_is_error(struct valid_tokens self)
{
  return self.bits == ~(~0U << (enum token_type)TOKEN_TYPE_LEN);
}

static void valid_tokens_debug(struct valid_tokens self)
{
  if (debug_mode) {
    DBG_F("valid tokens: [");
    for (int i = TOKEN_TYPE_START; i < TOKEN_TYPE_LEN; i++) {
      if (valid_tokens_test(self, i)) {
        (void)dprintf(" %s", TOKEN_TYPE_STR[i]);
      }
    }
    (void)dputs(" ]\n");
  }
}

#define FLAG_AFTER_NEWLINE 1U
#define FLAG_LEN 1U

typedef uint8_t flags_storage;

struct state {
  struct indent_vec layout_stack;
};

static struct state* state_new(void)
{
  struct state* result = ts_calloc(1, sizeof(struct state));
  if (!result) {
    return NULL;
  }
  return result;
}

static void state_destroy(struct state* self)
{
  if (self) {
    indent_vec_destroy(&self->layout_stack);
    ts_free(self);
  }
}

_nonnull_(1) static void state_clear(struct state* self)
{
  indent_vec_set_len(&self->layout_stack, 0);
}

_nonnull_(1, 2) static unsigned state_serialize(
    const struct state* self, char* buffer, unsigned buffer_len)
{
  unsigned serialize_len = 0;
  serialize_len += indent_vec_serialize(
      &self->layout_stack, &buffer[serialize_len], buffer_len - serialize_len);
  DBG_F("serialized %u bytes\n", serialize_len);
  return serialize_len;
}

_nonnull_(1) static void state_deserialize(
    struct state* self, const char* buffer, unsigned buffer_len)
{
  if (!buffer && buffer_len > 0) {
    DBG("error: no buffer but buffer length > 0");
    return;
  }

  unsigned idx = 0;
  state_clear(self);
  indent_vec_deserialize(&self->layout_stack, &buffer[idx], buffer_len - idx);
}

_nonnull_(1) static void state_debug(struct state* self)
{
  indent_vec_debug(&self->layout_stack);
}

struct context {
  TSLexer* _lexer;
  struct state* state;
  uint32_t advance_counter;
  struct valid_tokens valid_tokens;
  indent_value _current_indent;
  flags_storage flags : FLAG_LEN;
};

_nonnull_(1) static void context_mark_end(struct context* self)
{
  self->_lexer->mark_end(self->_lexer);
}

_nonnull_(1) _pure_ static uint32_t context_lookahead(struct context* self)
{
  return self->_lexer->lookahead;
}

_nonnull_(1) _pure_ static bool context_eof(struct context* self)
{
  return self->_lexer->eof(self->_lexer);
}

_nonnull_(1) static uint32_t context_advance(struct context* self, bool skip)
{
  self->advance_counter += (int)!context_eof(self);
  if (!context_eof(self)) {
    self->flags &= ~FLAG_AFTER_NEWLINE;
  }
  self->_lexer->advance(self->_lexer, skip);
  return self->_lexer->lookahead;
}

_nonnull_(1) static uint32_t context_consume(struct context* self, bool skip)
{
  uint32_t result = context_advance(self, skip);
  context_mark_end(self);
  return result;
}

_nonnull_(1) static bool context_finish(
    struct context* self, enum token_type type)
{
  DBG_F("finished scanning token: %s\n", TOKEN_TYPE_STR[type]);
  self->_lexer->result_symbol = (TSSymbol)type;
  return true;
}

_nonnull_(1) static indent_value context_indent(struct context* self)
{
  if (self->flags & FLAG_AFTER_NEWLINE) {
    return self->_current_indent;
  }

  return INVALID_INDENT_VALUE;
}

#define TRY_LEX_INNER(cnt, ctx, fn, ...)                          \
  do {                                                            \
    const uint32_t last_count_##cnt = (ctx)->advance_counter;     \
    if (fn((ctx), ##__VA_ARGS__)) {                               \
      return true;                                                \
    }                                                             \
    if ((ctx)->advance_counter != last_count_##cnt) return false; \
  } while (false)
/// Try lexing with the given function.
///
/// If the function succeed, the lexer returns immediately.
/// Otherwise, if no input were consumed, the lexer will continue.
///
/// The lexer will stop immediately if input was consumed and the given lexing
/// function fails.
///
/// @param ctx - The context to monitor state with, and as input to `fn`.
/// @param fn - The lexing function
#define TRY_LEX(ctx, fn, ...) TRY_LEX_INNER(__COUNTER__, ctx, fn, ##__VA_ARGS__)
#define LEX_FN(name, ...) \
  _nonnull_(1) static bool name(struct context* ctx, ##__VA_ARGS__)

_const_ static bool is_digit(uint32_t chr) { return chr >= '0' && chr <= '9'; }

_const_ static bool is_lower(uint32_t chr) { return chr >= 'a' && chr <= 'z'; }

_const_ static bool is_upper(uint32_t chr) { return chr >= 'A' && chr <= 'Z'; }

_const_ static bool is_keyword(uint32_t chr)
{
  return is_lower(chr) || is_upper(chr) || chr == '_';
}

_const_ static bool is_identifier(uint32_t chr)
{
  return is_keyword(chr) || is_digit(chr);
}

_const_ static uint32_t to_upper(uint32_t chr)
{
  const uint32_t lower_case_bit = 1U << 5U;
  return is_lower(chr) ? chr & ~lower_case_bit : chr;
}

_nonnull_(1) static size_t scan_spaces(struct context* ctx, bool force_update)
{
  bool update_indent = force_update;
  uint8_t indent = 0;
  size_t spaces = 0;
  while (true) {
    // Need goto to break out of loop
    // NOLINTBEGIN(*-avoid-goto)
    switch (context_lookahead(ctx)) {
    case ' ':
      indent += (int)(indent != INVALID_INDENT_VALUE);
      spaces++;
      context_advance(ctx, true);
      break;
    case '\n':
    case '\r':
      update_indent = true;
      indent = 0;
      spaces++;
      context_advance(ctx, true);
      break;
    case '\0':
      if (context_eof(ctx)) {
        update_indent = true;
        indent = 0;
      }
      goto loop_end;
    default:
      goto loop_end;
    }
    // NOLINTEND(*-avoid-goto)
  }
loop_end:
  if (update_indent) {
    DBG_F("updated current indentation: %" PRIu8 "\n", indent);
    ctx->_current_indent = indent;
    ctx->flags |= FLAG_AFTER_NEWLINE;
  }

  return spaces;
}

LEX_FN(lex_long_string_quote)
{
  if (context_lookahead(ctx) != '"' ||
      !valid_tokens_test(ctx->valid_tokens, LONG_STRING_QUOTE)) {
    return false;
  }

  context_consume(ctx, false);
  uint8_t count = 1;
  while (context_lookahead(ctx) == '"' && count < 3) {
    context_advance(ctx, false);
    count++;
  }

  if (count < 3) {
    context_mark_end(ctx);
    return context_finish(ctx, LONG_STRING_QUOTE);
  }

  if (context_lookahead(ctx) == '"') {
    return context_finish(ctx, LONG_STRING_QUOTE);
  }

  return false;
}

static const struct valid_tokens COMMENT_TOKENS = VALID_TOKENS(
    TO_VT_BIT(BLOCK_COMMENT_CONTENT) | TO_VT_BIT(BLOCK_DOC_COMMENT_CONTENT) |
    TO_VT_BIT(COMMENT_CONTENT));

LEX_FN(lex_comment_content)
{
  if (!valid_tokens_any_valid(ctx->valid_tokens, COMMENT_TOKENS) ||
      valid_tokens_is_error(ctx->valid_tokens)) {
    return false;
  }

  if (valid_tokens_test(ctx->valid_tokens, COMMENT_CONTENT)) {
    while (!context_eof(ctx)) {
      switch (context_lookahead(ctx)) {
      case '\n':
      case '\r':
        goto exit_short_comment_loop;
      default:
        context_advance(ctx, false);
      }
    }

exit_short_comment_loop:
    context_mark_end(ctx);
    return context_finish(ctx, COMMENT_CONTENT);
  }

  uint32_t nesting = 0;
  while (!context_eof(ctx)) {
    if (context_lookahead(ctx) == '#' && context_advance(ctx, false) == '[') {
      nesting++;
      DBG_F("block comment nest level: %" PRIu32 "\n", nesting);
    }
    context_mark_end(ctx);
    if (context_lookahead(ctx) == ']') {
      if (context_advance(ctx, false) == '#') {
        if (nesting > 0) {
          DBG_F("block comment terminate nest level: %" PRIu32 "\n", nesting);
          nesting--;
        }
        else if (valid_tokens_test(
                     ctx->valid_tokens, BLOCK_DOC_COMMENT_CONTENT)) {
          if (context_advance(ctx, false) == '#') {
            return context_finish(ctx, BLOCK_DOC_COMMENT_CONTENT);
          }
        }
        else {
          return context_finish(ctx, BLOCK_COMMENT_CONTENT);
        }
      }
      continue;
    }
    context_advance(ctx, false);
  }

  return false;
}

LEX_FN(lex_init)
{
  if (ctx->state->layout_stack.len > 0 ||
      valid_tokens_is_error(ctx->valid_tokens) ||
      valid_tokens_any_valid(ctx->valid_tokens, COMMENT_TOKENS)) {
    return false;
  }

  scan_spaces(ctx, true);
  if (context_lookahead(ctx) == '#') {
    return false;
  }

  indent_value current_indent = context_indent(ctx);
  if (current_indent == INVALID_INDENT_VALUE) {
    DBG("no valid indentation found");
    return false;
  }
  if (indent_vec_push(&ctx->state->layout_stack, current_indent) < 0) {
    DBG("could not extend layout stack");
    return false;
  };
  return context_finish(ctx, SYNCHRONIZE);
}

_nonnull_(1) static void skip_underscore(struct context* ctx)
{
  if (context_lookahead(ctx) == '_') {
    context_advance(ctx, false);
  }
}

static bool chrcaseeq(uint32_t lhs, uint32_t rhs)
{
  return to_upper(lhs) == to_upper(rhs);
}

LEX_FN(scan_continuing_keyword, bool scan_do)
{
#define NEXT_OR_FAIL(chr)                          \
  do {                                             \
    context_advance(ctx, false);                   \
    skip_underscore(ctx);                          \
    if (!chrcaseeq(context_lookahead(ctx), chr)) { \
      return false;                                \
    }                                              \
  } while (false)

// NOLINTNEXTLINE(cppcoreguidelines-macro-usage)
#define CONTINUE_ON(cond) \
  if (!(cond)) {          \
    return false;         \
  }

#define FINISH_IF_END                              \
  do {                                             \
    context_advance(ctx, false);                   \
    return !is_identifier(context_lookahead(ctx)); \
  } while (false)

  if (context_lookahead(ctx) == 'e') {
    context_advance(ctx, false);
    skip_underscore(ctx);
    if (chrcaseeq(context_lookahead(ctx), 'l')) {
      context_advance(ctx, false);
      skip_underscore(ctx);
      if (chrcaseeq(context_lookahead(ctx), 's')) {
        NEXT_OR_FAIL('e');
        FINISH_IF_END;
      }
      else if (chrcaseeq(context_lookahead(ctx), 'i')) {
        NEXT_OR_FAIL('f');
        FINISH_IF_END;
      }

      return false;
    }
    if (chrcaseeq(context_lookahead(ctx), 'x')) {
      NEXT_OR_FAIL('c');
      NEXT_OR_FAIL('e');
      NEXT_OR_FAIL('p');
      NEXT_OR_FAIL('t');
      FINISH_IF_END;
    }
  }

  if (context_lookahead(ctx) == 'f') {
    NEXT_OR_FAIL('i');
    NEXT_OR_FAIL('n');
    NEXT_OR_FAIL('a');
    NEXT_OR_FAIL('l');
    NEXT_OR_FAIL('l');
    NEXT_OR_FAIL('y');
    FINISH_IF_END;
  }

  if (scan_do) {
    if (context_lookahead(ctx) == 'd') {
      NEXT_OR_FAIL('o');
      FINISH_IF_END;
    }
  }

  return false;

#undef CASE_CHAR
#undef CONTINUE_ON
#undef NEXT_OR_FAIL
#undef FINISH_IF_END
}

LEX_FN(lex_case_of)
{
  if (context_lookahead(ctx) != 'o' ||
      !valid_tokens_test(ctx->valid_tokens, OF)) {
    return false;
  }

  skip_underscore(ctx);
  switch (context_advance(ctx, false)) {
  case 'f':
  case 'F':
    if (is_identifier(context_advance(ctx, false))) {
      return false;
    }
    context_mark_end(ctx);
    return context_finish(ctx, OF);
  default:
    return false;
  }
}

const struct valid_tokens NO_LAYOUT_END_CTX =
    VALID_TOKENS(TO_VT_BIT(INHIBIT_LAYOUT_END) | TO_VT_BIT(LONG_STRING_QUOTE));

// This function is big by design.
//
// NOLINTNEXTLINE(*-cognitive-complexity)
LEX_FN(lex_indent)
{
  if (context_lookahead(ctx) == '#' || ctx->state->layout_stack.len == 0) {
    return false;
  }

  indent_value current_indent = context_indent(ctx);
  if (current_indent == INVALID_INDENT_VALUE) {
    return false;
  }

  indent_value current_layout = indent_vec_back(&ctx->state->layout_stack);

  if (valid_tokens_test(ctx->valid_tokens, LAYOUT_START)) {
    if (current_indent > current_layout) {
      if (indent_vec_push(&ctx->state->layout_stack, current_indent) < 0) {
        DBG("could not extend layout stack");
        return false;
      }
      return context_finish(ctx, LAYOUT_START);
    }
  }

  if (valid_tokens_test(ctx->valid_tokens, LAYOUT_EMPTY)) {
    switch (0) {
    default:
      if (valid_tokens_is_error(ctx->valid_tokens)) {
        break;
      }
      if (current_indent <= current_layout) {
        return context_finish(ctx, LAYOUT_EMPTY);
      }
    }
  }

  if (valid_tokens_test(ctx->valid_tokens, LAYOUT_TERMINATOR)) {
    if (current_indent <= current_layout) {
      uint32_t last_count = ctx->advance_counter;
      if (current_indent == current_layout) {
        if (valid_tokens_test(ctx->valid_tokens, INHIBIT_KEYWORD_TERMINATION) &&
            scan_continuing_keyword(ctx, true)) {
          DBG("found continuing keyword");
          return false;
        }
        if (last_count == ctx->advance_counter) {
          if (lex_case_of(ctx)) {
            return true;
          }
        }
      }
      return context_finish(ctx, LAYOUT_TERMINATOR);
    }
  }

  // Implicit layout changes
  if (!valid_tokens_any_valid(ctx->valid_tokens, NO_LAYOUT_END_CTX) ||
      valid_tokens_is_error(ctx->valid_tokens) ||
      // Allow EOF to force a layout_end, which would lead to better error
      // recovery
      context_eof(ctx)) {
    // LAYOUT_END
    if (current_indent < current_layout || context_eof(ctx)) {
      if (ctx->state->layout_stack.len > 1) {
        indent_vec_pop(&ctx->state->layout_stack);
        return context_finish(ctx, LAYOUT_END);
      }
    }

    // INVALID_LAYOUT
    //
    // XXX: Need more data to reliably distinguish
    //
    // if (current_indent > current_layout && !context_eof(ctx)) {
    //   return context_finish(ctx, INVALID_LAYOUT);
    // }
  }

  TRY_LEX(ctx, lex_case_of);

  return false;
}

LEX_FN(lex_inline_layout)
{
  if (ctx->state->layout_stack.len == 0 || (ctx->flags & FLAG_AFTER_NEWLINE)) {
    return false;
  }

  switch (context_lookahead(ctx)) {
  case ',':
    if (valid_tokens_test(ctx->valid_tokens, COMMA)) {
      return false;
    }
    break;
  case ')':
  case ']':
  case '}':
    break;
  case '.':
    if (context_advance(ctx, false) == '}') {
      break;
    }
    return false;
  default:
    if (!valid_tokens_test(ctx->valid_tokens, INHIBIT_KEYWORD_TERMINATION) &&
        scan_continuing_keyword(ctx, false)) {
      break;
    }
    return false;
  }
  if (valid_tokens_test(ctx->valid_tokens, LAYOUT_TERMINATOR)) {
    DBG("terminate via inline element");
    return context_finish(ctx, LAYOUT_TERMINATOR);
  }

  if (valid_tokens_test(ctx->valid_tokens, LAYOUT_END) &&
      ctx->state->layout_stack.len > 1) {
    DBG("end layout via inline element");
    indent_vec_pop(&ctx->state->layout_stack);
    return context_finish(ctx, LAYOUT_END);
  }

  return false;
}

const struct valid_tokens UNARY_OPS =
    VALID_TOKENS(TO_VT_BIT(UNARY_OP) | TO_VT_BIT(SIGIL_OP));
const char OPERATOR_CHARS[] = {
    // OP10
    /* 0 */ '$', '^',
    // OP9
    /* 2 */ '*', '%', '\\', '/',
    // OP8
    /* 6 */ '+', '-', '~', '|',
    // OP7
    /* 10 */ '&',
    // OP6
    /* 11 */ '.',
    // OP5
    /* 12 */ '=', '<', '>', '!',
    // OP2
    /* 16 */ ':', '?', '@'};
const uint16_t UNICODE_OPERATOR_CHARS[] = {
    L'∙', L'∘', L'×', L'★', L'⊗', L'⊘', L'⊙', L'⊛', L'⊠', L'⊡', L'∩',
    L'∧', L'⊓', L'±', L'⊕', L'⊖', L'⊞', L'⊟', L'∪', L'∨', L'⊔',
};

_const_ static bool is_operator(uint32_t character)
{
  for (unsigned i = 0; i < sizeof(OPERATOR_CHARS); i++) {
    if ((uint32_t)OPERATOR_CHARS[i] == character) {
      return true;
    }
  }
  if (character > UINT8_MAX) {
    for (unsigned i = 0;
         i < sizeof(UNICODE_OPERATOR_CHARS) / sizeof(*UNICODE_OPERATOR_CHARS);
         i++) {
      if ((uint32_t)UNICODE_OPERATOR_CHARS[i] == character) {
        return true;
      }
    }
  }

  return false;
}

enum operator_scan_state {
  OS_REGULAR,
  OS_COLON,
  OS_COLON_COLON,
  OS_DOT,
  OS_EQUAL,
  OS_MINUS,
  OS_STAR,
};

#ifdef TREE_SITTER_INTERNAL_BUILD
const char* const OPERATOR_SCAN_STATE_STR[] = {
    [OS_REGULAR] = "REGULAR",
    "COLON",
    "COLON_COLON",
    "DOT",
    "EQUAL",
    "MINUS",
    "STAR"};
#endif

_nonnull_(1) static enum token_type scan_operator(
    struct context* ctx, bool immediate)
{
  if (immediate) {
    return TOKEN_TYPE_LEN;
  }

  enum operator_scan_state state = OS_REGULAR;
  const uint32_t first_character = context_lookahead(ctx);
  if (!is_operator(first_character)) {
    return TOKEN_TYPE_LEN;
  }

  switch (first_character) {
  case '.':
    context_advance(ctx, false);
    state = OS_DOT;
    break;
  case '=':
    context_advance(ctx, false);
    state = OS_EQUAL;
    break;
  case ':':
    context_advance(ctx, false);
    state = OS_COLON;
    break;
  case '-':
    context_advance(ctx, false);
    state = OS_MINUS;
    break;
  case '*':
    context_advance(ctx, false);
    state = OS_STAR;
    break;
  default:
    break;
  }

  while (is_operator(context_lookahead(ctx))) {
    switch (state) {
    case OS_STAR:
      switch (context_lookahead(ctx)) {
      case ':':
        goto loop_end;
      default:
        state = OS_REGULAR;
        break;
      }
      break;
    case OS_COLON:
      switch (context_lookahead(ctx)) {
      case ':':
        state = OS_COLON_COLON;
        context_advance(ctx, false);
        break;
      default:
        state = OS_REGULAR;
        break;
      }
      break;
    case OS_COLON_COLON:
    case OS_DOT:
    case OS_EQUAL:
    case OS_MINUS:
    case OS_REGULAR:
      state = OS_REGULAR;
      context_advance(ctx, false);
      break;
    }
  }
loop_end:
  switch (state) {
  case OS_EQUAL:
  case OS_COLON:
  case OS_COLON_COLON:
  case OS_DOT:
    return TOKEN_TYPE_LEN;
  case OS_MINUS:
    if (is_digit(context_lookahead(ctx))) {
      return TOKEN_TYPE_LEN;
    }
    break;
  case OS_STAR:
    if (valid_tokens_test(ctx->valid_tokens, WANT_EXPORT_MARKER)) {
      return TOKEN_TYPE_LEN;
    }
    break;
  default:
    break;
  }

  switch (context_lookahead(ctx)) {
  case ' ':
  case '\n':
  case '\r':
    return TOKEN_TYPE_LEN;
  default:
    return UNARY_OP;
  }
}

LEX_FN(lex_operators, bool immediate)
{
  if (!valid_tokens_any_valid(ctx->valid_tokens, UNARY_OPS)) {
    return false;
  }

  uint32_t first_character = context_lookahead(ctx);
  enum token_type result = scan_operator(ctx, immediate);
  if (result == TOKEN_TYPE_LEN) {
    if (first_character == '.') {
      TRY_LEX(ctx, lex_inline_layout);
    }
    return false;
  }

  result = first_character == '@' ? SIGIL_OP : UNARY_OP;
  DBG_F("operator final classification: %s\n", TOKEN_TYPE_STR[result]);

  if (!valid_tokens_test(ctx->valid_tokens, result)) {
    return false;
  }

  context_mark_end(ctx);
  return context_finish(ctx, result);
}

LEX_FN(lex_main)
{
  TRY_LEX(ctx, lex_init);

  TRY_LEX(ctx, lex_comment_content);
  TRY_LEX(ctx, lex_long_string_quote);

  size_t spaces = scan_spaces(ctx, false);

  TRY_LEX(ctx, lex_indent);
  TRY_LEX(ctx, lex_operators, spaces == 0);
  TRY_LEX(ctx, lex_inline_layout);

  return false;
}

void* tree_sitter_nim_external_scanner_create(void)
{
#ifdef TREE_SITTER_INTERNAL_BUILD
  debug_mode = getenv("TREE_SITTER_DEBUG");
#endif

  struct state* state = state_new();
  if (!state) {
    DBG("error: could not allocate a new state object!");
  }
  return state;
}

void tree_sitter_nim_external_scanner_destroy(void* payload)
{
  state_destroy((struct state*)payload);
}

unsigned tree_sitter_nim_external_scanner_serialize(
    void* payload, char* buffer)
{
  if (!payload || !buffer) {
    DBG("error: no payload or buffer");
    return 0;
  }
  return state_serialize(
      (struct state*)payload, buffer, TREE_SITTER_SERIALIZATION_BUFFER_SIZE);
}

void tree_sitter_nim_external_scanner_deserialize(
    void* payload, const char* buffer, unsigned length)
{
  if (!payload) {
    DBG("no payload, skipping");
    return;
  }
  state_deserialize((struct state*)payload, buffer, length);
}

bool tree_sitter_nim_external_scanner_scan(
    void* payload, TSLexer* lexer, const bool* valid_tokens)
{
  if (!payload || !lexer || !valid_tokens) {
    DBG("error: some parameters are not provided");
    return false;
  }

  DBG("begin");
  struct context ctx = {0};
  ctx._lexer = lexer;
  ctx.state = (struct state*)payload;
  ctx.valid_tokens = valid_tokens_from_array(valid_tokens);

  valid_tokens_debug(ctx.valid_tokens);
  state_debug(ctx.state);
  context_mark_end(&ctx);

  bool found = lex_main(&ctx);

  DBG(found ? "commit" : "end");
  state_debug(ctx.state);
  return found;
}

#include "tree_sitter/alloc.h"
#include "tree_sitter/array.h"
#include "tree_sitter/parser.h"

#include <string.h>
#include <wctype.h>

enum TokenType {
    OPT_SEMI,
    INTERPOLATION_REGULAR_START,
    INTERPOLATION_VERBATIM_START,
    INTERPOLATION_RAW_START,
    INTERPOLATION_START_QUOTE,
    INTERPOLATION_END_QUOTE,
    INTERPOLATION_OPEN_BRACE,
    INTERPOLATION_CLOSE_BRACE,
    INTERPOLATION_STRING_CONTENT,
    RAW_STRING_START,
    RAW_STRING_END,
    RAW_STRING_CONTENT,
    LAMBDA_PAREN_OPEN,
};

typedef enum {
    REGULAR = 1 << 0,
    VERBATIM = 1 << 1,
    RAW = 1 << 2,
} StringType;

typedef struct {
    uint8_t dollar_count;
    uint8_t open_brace_count;
    uint8_t quote_count;
    StringType string_type;
} Interpolation;

static inline bool is_regular(Interpolation *interpolation) { return interpolation->string_type & REGULAR; }

static inline bool is_verbatim(Interpolation *interpolation) { return interpolation->string_type & VERBATIM; }

static inline bool is_raw(Interpolation *interpolation) { return interpolation->string_type & RAW; }

typedef struct {
    uint8_t quote_count;
    Array(Interpolation) interpolation_stack;
} Scanner;

static inline void advance(TSLexer *lexer) { lexer->advance(lexer, false); }

static inline void skip(TSLexer *lexer) { lexer->advance(lexer, true); }

// ---- Helpers for LAMBDA_PAREN_OPEN scanning ---------------------------

static inline bool is_id_start(int32_t c) {
    return c == '_' || iswalpha(c);
}

static inline bool is_id_continue(int32_t c) {
    return c == '_' || iswalnum(c);
}

// Skip whitespace, line comments (//...), and block comments (/* ... */).
// Does NOT skip preprocessor directives — simple-lambda parameter lists
// cannot legally contain them.
static void skip_ws_and_comments(TSLexer *lexer) {
    for (;;) {
        int32_t c = lexer->lookahead;
        if (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
            advance(lexer);
        } else if (c == '/') {
            advance(lexer);
            if (lexer->lookahead == '/') {
                while (lexer->lookahead != 0 && lexer->lookahead != '\n') {
                    advance(lexer);
                }
            } else if (lexer->lookahead == '*') {
                advance(lexer);
                int32_t prev = 0;
                while (lexer->lookahead != 0 &&
                       !(prev == '*' && lexer->lookahead == '/')) {
                    prev = lexer->lookahead;
                    advance(lexer);
                }
                if (lexer->lookahead == '/') advance(lexer);
            } else {
                // a stray '/' isn't valid in a param list; bail out by
                // making the caller see something unexpected
                return;
            }
        } else {
            return;
        }
    }
}

// Consume an identifier into a fixed-size buffer. Returns the actual
// length consumed (may exceed `max`, in which case `buf` is only filled
// up to `max` bytes — useful for "too long to be a keyword" detection).
static size_t consume_identifier_into(TSLexer *lexer, char *buf, size_t max) {
    size_t n = 0;
    while (is_id_continue(lexer->lookahead)) {
        if (n < max) {
            buf[n] = (char)lexer->lookahead;
        }
        n++;
        advance(lexer);
    }
    return n;
}

// True iff the first `n` bytes of `buf` equal the C string `kw`.
static bool buf_equals(const char *buf, size_t n, const char *kw) {
    size_t klen = strlen(kw);
    return n == klen && memcmp(buf, kw, klen) == 0;
}

void *tree_sitter_c_sharp_external_scanner_create() {
    Scanner *scanner = ts_calloc(1, sizeof(Scanner));
    array_init(&scanner->interpolation_stack);
    return scanner;
}

void tree_sitter_c_sharp_external_scanner_destroy(void *payload) {
    Scanner *scanner = (Scanner *)payload;
    array_delete(&scanner->interpolation_stack);
    ts_free(scanner);
}

unsigned tree_sitter_c_sharp_external_scanner_serialize(void *payload, char *buffer) {
    Scanner *scanner = (Scanner *)payload;

    if (scanner->interpolation_stack.size * 4 + 2 > TREE_SITTER_SERIALIZATION_BUFFER_SIZE) {
        return 0;
    }

    unsigned size = 0;

    buffer[size++] = (char)scanner->quote_count;
    buffer[size++] = (char)scanner->interpolation_stack.size;

    for (unsigned i = 0; i < scanner->interpolation_stack.size; i++) {
        Interpolation interpolation = scanner->interpolation_stack.contents[i];
        buffer[size++] = (char)interpolation.dollar_count;
        buffer[size++] = (char)interpolation.open_brace_count;
        buffer[size++] = (char)interpolation.quote_count;
        buffer[size++] = (char)interpolation.string_type;
    }

    return size;
}

void tree_sitter_c_sharp_external_scanner_deserialize(void *payload, const char *buffer, unsigned length) {
    Scanner *scanner = (Scanner *)payload;

    scanner->quote_count = 0;
    array_clear(&scanner->interpolation_stack);
    unsigned size = 0;

    if (length > 0) {
        scanner->quote_count = (unsigned char)buffer[size++];
        scanner->interpolation_stack.size = (unsigned char)buffer[size++];
        array_reserve(&scanner->interpolation_stack, scanner->interpolation_stack.size);

        for (unsigned i = 0; i < scanner->interpolation_stack.size; i++) {
            Interpolation interpolation = {0};
            interpolation.dollar_count = buffer[size++];
            interpolation.open_brace_count = buffer[size++];
            interpolation.quote_count = buffer[size++];
            interpolation.string_type = (unsigned char)buffer[size++];
            scanner->interpolation_stack.contents[i] = interpolation;
        }
    }

    assert(size == length);
}

// Outcome of `scan_lambda_paren_open` — distinguishes "didn't start"
// (lexer untouched, wrapper can fall through to other token handlers)
// from "started and failed" (lexer cursor advanced past characters
// the wrapper must not let other handlers consume — they would emit
// tokens with wrong spans, e.g. an `INTERPOLATION_REGULAR_START`
// span covering `(false, $` in `return (false, $"...");`).
typedef enum {
    LAMBDA_SCAN_NO_PAREN,         // not a '(', no advance() done
    LAMBDA_SCAN_FAILED_AFTER_PAREN, // '(' was consumed, dirty state
    LAMBDA_SCAN_SUCCESS,
} LambdaScanResult;

// Try to recognize a C# 14 simple-lambda parameter list at the current
// position. On SUCCESS, `lexer->result_symbol` is LAMBDA_PAREN_OPEN
// and `mark_end` is set on the opening '('. On NO_PAREN, the lexer is
// untouched (only `skip(lexer)` over leading whitespace, which doesn't
// participate in token boundaries). On FAILED_AFTER_PAREN, the lexer
// has advanced past at least the opening '(' and the caller must
// surface this as a false return from the external_scanner_scan
// function so tree-sitter rewinds.
//
// Grammar of the pattern (after the opening '('):
//
//   element (',' element)* ')' '=>'
//
//   element  := modifier+ identifier
//             | identifier
//
//   modifier ∈ { scoped, ref, out, in, readonly }
//
// At least one element must carry a modifier; otherwise we'd over-fire
// on plain `(x, y) => ...` which is already handled by the existing
// `_lambda_parameters` choice.
//
// Implementation note: identifier-tokens are consumed *whole* into a
// small buffer before being classified as modifier-or-name. A
// character-by-character probe against each candidate keyword would be
// unworkable because `ref` is a prefix of `readonly` (they share `re`)
// and TSLexer has no rewind primitive: any probe order leaves one of
// the two keywords unreachable. Buffering the whole identifier
// sidesteps the prefix conflict entirely.
static LambdaScanResult scan_lambda_paren_open(TSLexer *lexer) {
    // External scanners run before whitespace `extras` are skipped, so
    // we need to skip leading whitespace/comments ourselves before
    // checking for the opening '('. `skip(lexer)` consumes the char as
    // an extra (not part of any token), so even on NO_PAREN return the
    // wrapper's fall-through into other handlers is safe — those
    // handlers do their own whitespace skipping.
    while (iswspace(lexer->lookahead)) {
        skip(lexer);
    }
    if (lexer->lookahead != '(') return LAMBDA_SCAN_NO_PAREN;
    advance(lexer);
    lexer->mark_end(lexer);

    // From this point on, the lexer cursor has moved past '('. Any
    // return must be FAILED_AFTER_PAREN unless we reach SUCCESS.
    #define BAIL return LAMBDA_SCAN_FAILED_AFTER_PAREN

    // We require at least one "hard" modifier (ref/out/in/readonly) across
    // the whole list before committing. `scoped` alone is not a valid C#
    // parameter modifier — it must always combine with a hard modifier —
    // and `scoped` is also a legal type name, so accepting `(scoped x) =>`
    // as a modifier+name pair would collide with the existing
    // `parameter_list` path on input that semantically means
    // type+identifier.
    bool saw_hard_modifier = false;
    bool expecting_element = true;

    for (;;) {
        skip_ws_and_comments(lexer);
        int32_t c = lexer->lookahead;

        if (c == 0) BAIL;   // EOF mid-list

        if (c == ')') {
            advance(lexer);
            skip_ws_and_comments(lexer);
            if (!saw_hard_modifier) BAIL;
            if (lexer->lookahead != '=') BAIL;
            advance(lexer);
            if (lexer->lookahead != '>') BAIL;
            lexer->result_symbol = LAMBDA_PAREN_OPEN;
            return LAMBDA_SCAN_SUCCESS;
        }

        if (!expecting_element) {
            if (c != ',') BAIL;
            advance(lexer);
            expecting_element = true;
            continue;
        }

        // Consume identifier-tokens in this element. Each one is either a
        // parameter modifier (`scoped`/`ref`/`out`/`in`/`readonly`) — in which
        // case we continue looking for more — or the parameter name, which
        // ends the element. Consuming the whole token before classifying
        // avoids any need to rewind the lexer on a prefix-conflict (e.g. ref
        // vs readonly).
        bool consumed_name = false;
        while (!consumed_name) {
            skip_ws_and_comments(lexer);
            if (!is_id_start(lexer->lookahead)) BAIL;

            char buf[9];  // "readonly" is 8 chars
            size_t n = consume_identifier_into(lexer, buf, sizeof(buf));

            bool is_hard_modifier = (n <= 8) && (
                buf_equals(buf, n, "ref") ||
                buf_equals(buf, n, "out") ||
                buf_equals(buf, n, "in") ||
                buf_equals(buf, n, "readonly")
            );
            bool is_soft_modifier = (n == 6) && buf_equals(buf, n, "scoped");

            if (is_hard_modifier) {
                saw_hard_modifier = true;
            } else if (is_soft_modifier) {
                // `scoped` is a modifier only when followed by a hard
                // modifier; keep scanning. If the element turns out to
                // end with `scoped <identifier>` and no hard modifier
                // appeared, the final `saw_hard_modifier` check fails
                // and we fall back to the regular parameter_list path.
            } else {
                consumed_name = true;
            }
        }
        expecting_element = false;
    }
}
#undef BAIL

bool tree_sitter_c_sharp_external_scanner_scan(void *payload, TSLexer *lexer, const bool *valid_symbols) {
    Scanner *scanner = (Scanner *)payload;

    uint8_t brace_advanced = 0;
    uint8_t quote_count = 0;
    bool did_advance = false;

    // Lambda-paren scanning advances forward speculatively past the
    // opening `(`. If it consumes input and then bails, the lexer
    // cursor is mispositioned and must not be reused by other token
    // handlers below — they would emit tokens with spans starting at
    // the original scan position but ending at the dirty cursor (e.g.
    // an INTERPOLATION_REGULAR_START swallowing `(false, $` in
    // `return (false, $"...");`). When the scanner consumed `(` but
    // didn't confirm a lambda, return false here so tree-sitter
    // rewinds and lets the built-in `(` tokenizer match.
    if (valid_symbols[LAMBDA_PAREN_OPEN]) {
        switch (scan_lambda_paren_open(lexer)) {
            case LAMBDA_SCAN_SUCCESS:
                return true;
            case LAMBDA_SCAN_FAILED_AFTER_PAREN:
                return false;
            case LAMBDA_SCAN_NO_PAREN:
                break;  // lexer untouched; fall through
        }
    }

    // error recovery, gives better trees this way
    if (valid_symbols[OPT_SEMI] && valid_symbols[INTERPOLATION_REGULAR_START]) {
        return false;
    }

    if (valid_symbols[OPT_SEMI]) {
        lexer->result_symbol = OPT_SEMI;
        if (lexer->lookahead == ';') {
            advance(lexer);
        }
        return true;
    }

    if (valid_symbols[RAW_STRING_START]) {
        while (iswspace(lexer->lookahead)) {
            skip(lexer);
        }

        if (lexer->lookahead == '"') {
            while (lexer->lookahead == '"') {
                advance(lexer);
                quote_count++;
            }

            if (quote_count >= 3) {
                lexer->result_symbol = RAW_STRING_START;
                scanner->quote_count = quote_count;
                return true;
            }
        }
    }

    if (valid_symbols[RAW_STRING_END] && lexer->lookahead == '"') {
        while (lexer->lookahead == '"') {
            advance(lexer);
            quote_count++;
        }

        if (quote_count == scanner->quote_count) {
            lexer->result_symbol = RAW_STRING_END;
            scanner->quote_count = 0;
            return true;
        }

        did_advance = quote_count > 0;
    }

    if (valid_symbols[RAW_STRING_CONTENT]) {
        while (lexer->lookahead) {
            if (lexer->lookahead == '"') {
                lexer->mark_end(lexer);
                quote_count = 0;

                while (lexer->lookahead == '"') {
                    advance(lexer);
                    quote_count++;
                }

                if (quote_count == scanner->quote_count) {
                    lexer->result_symbol = RAW_STRING_CONTENT;
                    return true;
                }
            }
            advance(lexer);
            did_advance = true;
        }
        lexer->mark_end(lexer);
        lexer->result_symbol = RAW_STRING_CONTENT;
        return true;
    }

    if (valid_symbols[INTERPOLATION_REGULAR_START] || valid_symbols[INTERPOLATION_VERBATIM_START] ||
        valid_symbols[INTERPOLATION_RAW_START]) {
        while (iswspace(lexer->lookahead)) {
            skip(lexer);
        }

        uint8_t dollar_advanced = 0;

        bool is_verbatim = false;

        if (lexer->lookahead == '@') {
            is_verbatim = true;
            advance(lexer);
        }

        while (lexer->lookahead == '$' && quote_count == 0) {
            advance(lexer);
            dollar_advanced++;
        }

        if (dollar_advanced > 0 && (lexer->lookahead == '"' || lexer->lookahead == '@')) {
            lexer->result_symbol = INTERPOLATION_REGULAR_START;
            Interpolation interpolation = {
                .dollar_count = dollar_advanced,
                .open_brace_count = 0,
                .quote_count = 0,
                .string_type = 0,
            };

            if (is_verbatim || lexer->lookahead == '@') {
                if (lexer->lookahead == '@') {
                    advance(lexer);
                    is_verbatim = true;
                }
                lexer->result_symbol = INTERPOLATION_VERBATIM_START;
                interpolation.string_type = VERBATIM;
            }

            lexer->mark_end(lexer);
            advance(lexer);

            if (lexer->lookahead == '"' && !is_verbatim) {
                advance(lexer);
                if (lexer->lookahead == '"') {
                    lexer->result_symbol = INTERPOLATION_RAW_START;
                    interpolation.string_type |= RAW;
                    array_push(&scanner->interpolation_stack, interpolation);
                }
                // If we find 1 or 3 quotes, we push an interpolation.
                // If there's only two quotes, that's just an empty string
            } else {
                interpolation.string_type |= REGULAR;
                array_push(&scanner->interpolation_stack, interpolation);
            }

            return true;
        }
    }

    if (valid_symbols[INTERPOLATION_START_QUOTE] && scanner->interpolation_stack.size > 0) {
        Interpolation *current_interpolation = array_back(&scanner->interpolation_stack);

        if (is_verbatim(current_interpolation) || is_regular(current_interpolation)) {
            if (lexer->lookahead == '"') {
                advance(lexer);
                current_interpolation->quote_count++;
            }
        } else {
            while (lexer->lookahead == '"') {
                advance(lexer);
                current_interpolation->quote_count++;
            }
        }

        lexer->result_symbol = INTERPOLATION_START_QUOTE;
        return current_interpolation->quote_count > 0;
    }

    if (valid_symbols[INTERPOLATION_END_QUOTE] && scanner->interpolation_stack.size > 0) {
        Interpolation *current_interpolation = array_back(&scanner->interpolation_stack);

        while (lexer->lookahead == '"') {
            advance(lexer);
            quote_count++;
        }

        if (quote_count == current_interpolation->quote_count) {
            lexer->result_symbol = INTERPOLATION_END_QUOTE;
            array_pop(&scanner->interpolation_stack);
            return true;
        }

        did_advance = quote_count > 0;
    }

    if (valid_symbols[INTERPOLATION_OPEN_BRACE] && scanner->interpolation_stack.size > 0) {
        Interpolation *current_interpolation = array_back(&scanner->interpolation_stack);

        while (lexer->lookahead == '{' && brace_advanced < current_interpolation->dollar_count) {
            advance(lexer);
            brace_advanced++;
        }

        if (brace_advanced > 0 && brace_advanced == current_interpolation->dollar_count &&
            (brace_advanced == 0 || lexer->lookahead != '{')) {
            current_interpolation->open_brace_count = brace_advanced;
            lexer->result_symbol = INTERPOLATION_OPEN_BRACE;
            return true;
        }
    }

    if (valid_symbols[INTERPOLATION_CLOSE_BRACE] && scanner->interpolation_stack.size > 0) {
        uint8_t brace_advanced = 0;
        Interpolation *current_interpolation = array_back(&scanner->interpolation_stack);

        while (iswspace(lexer->lookahead)) {
            advance(lexer);
        }

        while (lexer->lookahead == '}') {
            advance(lexer);
            brace_advanced++;

            if (brace_advanced == current_interpolation->open_brace_count) {
                current_interpolation->open_brace_count = 0;
                lexer->result_symbol = INTERPOLATION_CLOSE_BRACE;
                return true;
            }
        }

        return false;
    }

    if (valid_symbols[INTERPOLATION_STRING_CONTENT] && scanner->interpolation_stack.size > 0) {
        lexer->result_symbol = INTERPOLATION_STRING_CONTENT;
        Interpolation *current_interpolation = array_back(&scanner->interpolation_stack);

        while (lexer->lookahead) {
            // top-down approach, first see if it's raw
            if (is_raw(current_interpolation)) {
                if (lexer->lookahead == '"') {
                    lexer->mark_end(lexer);
                    advance(lexer);
                    if (lexer->lookahead == '"') {
                        advance(lexer);
                        uint8_t quote_advanced = 2;
                        while (lexer->lookahead == '"') {
                            quote_advanced++;
                            advance(lexer);
                        }
                        if (quote_advanced == current_interpolation->quote_count) {
                            return did_advance;
                        }
                    }
                }

                if (lexer->lookahead == '{') {
                    lexer->mark_end(lexer);

                    while (lexer->lookahead == '{' && brace_advanced < current_interpolation->open_brace_count) {
                        advance(lexer);
                        brace_advanced++;
                    }

                    if (brace_advanced == current_interpolation->open_brace_count &&
                        (brace_advanced == 0 || lexer->lookahead != '{')) {
                        return did_advance;
                    }
                }
            }

            // then verbatim, since it could be verbatim + raw, but run the raw branch first
            else if (is_verbatim(current_interpolation)) {
                if (lexer->lookahead == '"') {
                    lexer->mark_end(lexer);
                    advance(lexer);
                    if (lexer->lookahead == '"') {
                        advance(lexer);
                        continue;
                    }
                    return did_advance;
                }

                if (lexer->lookahead == '{') {
                    lexer->mark_end(lexer);

                    while (lexer->lookahead == '{' && brace_advanced < current_interpolation->open_brace_count) {
                        advance(lexer);
                        brace_advanced++;
                    }

                    if (brace_advanced == current_interpolation->open_brace_count &&
                        (brace_advanced == 0 || lexer->lookahead != '{')) {
                        return did_advance;
                    }
                }
            }

            // finally regular
            else if (is_regular(current_interpolation)) {
                if (lexer->lookahead == '\\' || lexer->lookahead == '\n' || lexer->lookahead == '"') {
                    lexer->mark_end(lexer);
                    return did_advance;
                }

                if (lexer->lookahead == '{') {
                    lexer->mark_end(lexer);

                    while (lexer->lookahead == '{' && brace_advanced < current_interpolation->open_brace_count) {
                        advance(lexer);
                        brace_advanced++;
                    }

                    if (brace_advanced == current_interpolation->open_brace_count &&
                        (brace_advanced == 0 || lexer->lookahead != '{')) { // if we're in a brace we're not allowed to
                                                                            // collect more than the open_brace_count
                        return did_advance;
                    }
                }
            }

            if (lexer->lookahead != '{') {
                brace_advanced = 0;
            }
            advance(lexer);
            did_advance = true;
        }

        lexer->mark_end(lexer);
        return did_advance;
    }

    return false;
}

#include "tree_sitter/array.h"
#include "tree_sitter/parser.h"

#include <string.h>
#include <wctype.h>

// Mostly a copy paste of tree-sitter-javascript/src/scanner.c

enum TokenType {
  AUTOMATIC_SEMICOLON,
  MULTILINE_COMMENT,
  STRING_START,
  STRING_END,
  STRING_CONTENT,
  PRIMARY_CONSTRUCTOR_KEYWORD,
  IMPORT_DOT,
  INTERPOLATION_EXPRESSION_START,
  INTERPOLATION_IDENTIFIER_START,
  BY_DELEGATION_HINT,
};

/* Pretty much all of this code is taken from the Julia tree-sitter
   parser.

   Julia has similar problems with multiline comments that can be nested,
   line comments, as well as line and multiline strings.

   The most heavily edited section is `scan_string_content`,
   particularly with respect to interpolation.
 */

// Block comments are easy to parse, but strings require extra-attention.

// The main problems that arise when parsing strings are:
// 1. Triple quoted strings allow single quotes inside. e.g. """ "foo" """.
// 2. Non-standard string literals don't allow interpolations or escape
//    sequences, but you can always write \" and \`.

// To efficiently store a delimiter, we take advantage of the fact that:
// (int)'"' == 34 && (34 & 1) == 0
// i.e. " has an even numeric representation, so we can store a triple
// quoted delimiter as (delimiter + 1).

#define DELIMITER_LENGTH 3

typedef char Delimiter;

// We use a stack to keep track of the string delimiters.
// Each entry is two bytes: [delimiter_byte, prefix_len_byte].
// delimiter_byte: '"' for single-quoted, '"'+1 for triple-quoted.
// prefix_len_byte: number of '$' signs required to trigger interpolation
//   (1 for regular strings and $"...", 2 for $$"...", etc.; max 255).
typedef Array(Delimiter) Stack;

static inline void stack_push(Stack *stack, char chr, bool triple, uint8_t prefix_len) {
  if (stack->size + 1 >= TREE_SITTER_SERIALIZATION_BUFFER_SIZE) abort();
  array_push(stack, (Delimiter)(triple ? (chr + 1) : chr));
  array_push(stack, (Delimiter)prefix_len);
}

static inline void stack_pop(Stack *stack) {
  if (stack->size < 2) abort();
  stack->size -= 2;
}

static inline void skip(TSLexer *lexer) { lexer->advance(lexer, true); }

static inline void advance(TSLexer *lexer) { lexer->advance(lexer, false); }

// Scanner functions

static bool scan_string_start(TSLexer *lexer, Stack *stack) {
  // Count leading '$' signs (the interpolation prefix). Capped at 255.
  uint8_t prefix_len = 0;
  while (lexer->lookahead == '$') {
    advance(lexer);
    if (prefix_len < 255) prefix_len++;
  }
  // Regular strings with no prefix still use a single '$' as the trigger.
  if (prefix_len == 0) prefix_len = 1;

  if (lexer->lookahead != '"') return false;
  advance(lexer);
  lexer->mark_end(lexer);
  for (unsigned count = 1; count < DELIMITER_LENGTH; ++count) {
    if (lexer->lookahead != '"') {
      // It's not a triple quoted delimiter.
      stack_push(stack, '"', false, prefix_len);
      return true;
    }
    advance(lexer);
  }
  lexer->mark_end(lexer);
  stack_push(stack, '"', true, prefix_len);
  return true;
}

static bool scan_string_content(TSLexer *lexer, Stack *stack,
                                const bool *valid_symbols) {
  if (stack->size < 2) return false;  // Stack is empty. We're not in a string.
  uint8_t prefix_len = (uint8_t)stack->contents[stack->size - 1];
  Delimiter raw_delim = stack->contents[stack->size - 2];
  bool is_triple = (raw_delim & 1) != 0;
  char end_char = is_triple ? (char)(raw_delim - 1) : (char)raw_delim;
  bool has_content = false;
  while (true) {
    if (lexer->lookahead == '\0') {
      // Stop at real end-of-input, but treat a literal NUL byte (not EOF) as
      // ordinary string content: consume it to guarantee forward progress.
      // Returning here without advancing would leave the lexer stuck at the
      // same offset (mirrors the NUL handling in scan_multiline_comment).
      if (lexer->eof(lexer)) break;
      advance(lexer);
      has_content = true;
      continue;
    }
    if (lexer->lookahead == '$') {
      // If we already have content, stop here so the caller can emit it
      // before we deal with the potential interpolation.
      if (has_content) {
        lexer->result_symbol = STRING_CONTENT;
        return true;
      }
      // Kotlin 2.1 multi-dollar interpolation: in a string with prefix_len N,
      // exactly N consecutive '$' followed by alpha/'{' triggers interpolation.
      // Excess leading '$' signs are literal string content.
      //
      // Strategy: consume the first '$' and mark_end there, then count
      // remaining '$' signs. If total > prefix_len, return STRING_CONTENT
      // for just the first '$' (tree-sitter rewinds to mark_end). On the
      // next scan call, the remaining dollars will be re-examined.
      advance(lexer);
      lexer->mark_end(lexer);
      uint16_t additional_dollars = 0;
      while (lexer->lookahead == '$') {
        advance(lexer);
        additional_dollars++;
      }
      uint16_t total_dollars = 1 + additional_dollars;
      if (total_dollars >= prefix_len &&
          (iswalpha(lexer->lookahead) || lexer->lookahead == '_' || lexer->lookahead == '{')) {
        if (total_dollars > prefix_len) {
          // Excess: emit first '$' as literal STRING_CONTENT.
          // mark_end is after the first '$'; tree-sitter rewinds there.
          lexer->result_symbol = STRING_CONTENT;
          return true;
        }
        // Exact match: emit interpolation start token.
        if (additional_dollars > 0) {
          lexer->mark_end(lexer);
        }
        if (valid_symbols[INTERPOLATION_EXPRESSION_START] &&
            lexer->lookahead == '{') {
          advance(lexer);
          // Empty interpolation "${}" is invalid Kotlin (compile error:
          // "Expecting an expression"). Refuse to emit the interpolation
          // token so the parser produces an ERROR node instead of matching
          // a zero-width expression.
          if (lexer->lookahead == '}') {
            return false;
          }
          lexer->mark_end(lexer);
          lexer->result_symbol = INTERPOLATION_EXPRESSION_START;
          return true;
        }
        if (valid_symbols[INTERPOLATION_IDENTIFIER_START] &&
            (iswalpha(lexer->lookahead) || lexer->lookahead == '_')) {
          lexer->result_symbol = INTERPOLATION_IDENTIFIER_START;
          return true;
        }
        return false;
      }
      // Not enough '$' signs or not followed by alpha/'{':
      // all consumed dollars are literal string content.
      if (additional_dollars > 0) {
        lexer->mark_end(lexer);
      }
      lexer->result_symbol = STRING_CONTENT;
      return true;
    }
    if (lexer->lookahead == '\\') {
      // if we see a \, then this might possibly escape a dollar sign
      // in which case, we should not defer to the interpolation
      advance(lexer);
      // this dollar sign is escaped, so it must be content.
      // we consume it here so we don't enter the dollar sign case above,
      // which leaves the possibility that it is an interpolation 
      if (lexer->lookahead == '$') {
        advance(lexer);
        // however this leaves an edgecase where an escaped dollar sign could
        // appear at the end of a string (e.g "aa\$") which isn't handled
        // correctly; if we were at the end of the string, terminate properly
        if (lexer->lookahead == end_char) {
          stack_pop(stack);
          advance(lexer);
          lexer->mark_end(lexer);
          lexer->result_symbol = STRING_END;
          return true;
        }
      } else if (is_triple && lexer->lookahead == end_char) {
        // In triple-quoted strings, `\` is NOT an escape character. So `\"` is
        // also literal backslash + quote, and the `"` might be the start of
        // the closing `"""`. Don't advance past it (at the end of the while
        // loop). Let the next iteration handle it.
        has_content = true;
        continue;
      }
    } else if (lexer->lookahead == end_char) {
      if (is_triple) {
        lexer->mark_end(lexer);
        for (unsigned count = 1; count < DELIMITER_LENGTH; ++count) {
          advance(lexer);
          if (lexer->lookahead != end_char) {
            lexer->mark_end(lexer);
            lexer->result_symbol = STRING_CONTENT;
            return true;
          }
        }

        /* This is so if we lex something like
           """foo"""
              ^
           where we are at the `f`, we should quit after
           reading `foo`, and ascribe it to STRING_CONTENT.

           Then, we restart and try to read the end.
           This is to prevent `foo` from being absorbed into
           the STRING_END token.
         */
        if (has_content && lexer->lookahead == end_char) {
          lexer->result_symbol = STRING_CONTENT;
          return true;
        }

        /* Since the string internals are all hidden in the syntax
           tree anyways, there's no point in going to the effort of
           specifically separating the string end from string contents.
           If we see a bunch of quotes in a row, then we just go until
           they stop appearing, then stop lexing and call it the
           string's end.
         */
        lexer->result_symbol = STRING_END;
        lexer->mark_end(lexer);
        while (lexer->lookahead == end_char) {
          advance(lexer);
          lexer->mark_end(lexer);
        }
        stack_pop(stack);
        return true;
      }
      if (has_content) {
        lexer->mark_end(lexer);
        lexer->result_symbol = STRING_CONTENT;
        return true;
      }
      stack_pop(stack);
      advance(lexer);
      lexer->mark_end(lexer);
      lexer->result_symbol = STRING_END;
      return true;
    }
    advance(lexer);
    has_content = true;
  }
  return false;
}


static bool scan_multiline_comment(TSLexer *lexer) {
  if (lexer->lookahead != '/') return false;
  advance(lexer);
  if (lexer->lookahead != '*') return false;
  advance(lexer);

  bool after_star = false;
  unsigned nesting_depth = 1;
  for (;;) {
    switch (lexer->lookahead) {
      case '*':
        advance(lexer);
        after_star = true;
        break;
      case '/':
        advance(lexer);
        if (after_star) {
          after_star = false;
          nesting_depth -= 1;
          if (nesting_depth == 0) {
            lexer->result_symbol = MULTILINE_COMMENT;
            lexer->mark_end(lexer);
            return true;
          }
        } else {
          after_star = false;
          if (lexer->lookahead == '*') {
            nesting_depth += 1;
            advance(lexer);
          }
        }
        break;
      case '\0':
        // Accept unterminated block comments at EOF rather than rejecting them.
        // This matches JetBrains PSI behavior which recognizes unclosed /* as a
        // BLOCK_COMMENT token (plus an error element). Without this, the scanner
        // returns false and tree-sitter tries to parse the comment delimiters
        // as operators/expressions.
        if (lexer->eof(lexer)) {
          lexer->result_symbol = MULTILINE_COMMENT;
          lexer->mark_end(lexer);
          return true;
        }
        // A literal NUL byte inside the comment (lookahead is '\0' but not EOF)
        // must be consumed like any other comment content. Returning here without
        // advancing leaves the lexer at the same offset, so tree-sitter re-invokes
        // the scanner forever on inputs such as "/*\0" -> a parse-time hang (DoS).
        // fallthrough
      default:
        advance(lexer);
        after_star = false;
        break;
    }
  }
}

static bool scan_whitespace_and_comments(TSLexer *lexer) {
  while (iswspace(lexer->lookahead)) skip(lexer);
  return true;
}

// Test for any identifier character other than the first character.
// This is meant to match the regexp [\p{L}_\p{Nd}]
// as found in '_alpha_identifier' (see grammar.js).
static bool is_word_char(int32_t c) {
  return (iswalnum(c) || c == '_');
}

// Scan for [the end of] a nonempty alphanumeric identifier or
// alphanumeric keyword (including '_').
static bool scan_for_word(TSLexer *lexer, const char* word, unsigned len) {
    skip(lexer);
    for (unsigned i = 0; i < len; ++i) {
      if (lexer->lookahead != word[i]) return false;
      skip(lexer);
    }
    // check that the identifier stops here
    if (is_word_char(lexer->lookahead)) return false;
    return true;
}

// Check if a sequence of characters matches the given word and is followed
// by a non-word character. Uses skip() so characters are not included in
// the current token.
static bool check_word(TSLexer *lexer, const char *word, unsigned len) {
  for (unsigned i = 0; i < len; i++) {
    if (lexer->lookahead != word[i]) return false;
    skip(lexer);
  }
  return !is_word_char(lexer->lookahead);
}

// Skip whitespace (space, tab, newline, CR) and comments (// and nested /* */)
// using skip() so characters are not included in the current token.
// Returns false if a bare '/' is encountered (not a comment), true otherwise.
static bool skip_whitespace_and_comments(TSLexer *lexer) {
  for (;;) {
    while (iswspace(lexer->lookahead)) skip(lexer);
    if (lexer->lookahead != '/') return true;
    skip(lexer);
    if (lexer->lookahead == '/') {
      // Line comment — skip to end of line
      skip(lexer);
      while (lexer->lookahead != '\n' && lexer->lookahead != '\r' &&
             !lexer->eof(lexer)) {
        skip(lexer);
      }
    } else if (lexer->lookahead == '*') {
      // Block comment — skip to */ (with nesting)
      skip(lexer);
      unsigned depth = 1;
      while (depth > 0 && !lexer->eof(lexer)) {
        if (lexer->lookahead == '*') {
          skip(lexer);
          if (lexer->lookahead == '/') { skip(lexer); depth--; }
        } else if (lexer->lookahead == '/') {
          skip(lexer);
          if (lexer->lookahead == '*') { skip(lexer); depth++; }
        } else {
          skip(lexer);
        }
      }
    } else {
      // Bare '/' — not a comment
      return false;
    }
  }
}

// After scan_for_word has matched "else", peek past optional whitespace
// and comments for "->". If found, this is a when-entry's `else ->`,
// not an if-else. Uses skip() so characters are not included in the
// current token.
static bool followed_by_arrow(TSLexer *lexer) {
  if (!skip_whitespace_and_comments(lexer)) return false;
  if (lexer->lookahead != '-') return false;
  skip(lexer);
  return lexer->lookahead == '>';
}

// Check if the current position has a visibility modifier (public, private,
// protected, internal) followed by horizontal whitespace and "constructor".
// Uses skip() — safe to call speculatively since no token boundary is changed.
static bool check_modifier_then_constructor(TSLexer *lexer) {
  // Buffer the first word to identify the modifier
  char word[20];
  unsigned len = 0;
  while (is_word_char(lexer->lookahead) && len < 19) {
    word[len++] = (char)lexer->lookahead;
    skip(lexer);
  }
  word[len] = '\0';

  if (strcmp(word, "public") != 0 && strcmp(word, "private") != 0 &&
      strcmp(word, "protected") != 0 && strcmp(word, "internal") != 0) {
    return false;
  }

  // Skip horizontal whitespace (not newlines)
  while (lexer->lookahead == ' ' || lexer->lookahead == '\t') skip(lexer);

  return check_word(lexer, "constructor", 11);
}

// Look ahead past one or more annotations (e.g. @Bar, @com.example.Bar,
// @Bar(x=1)) and optional visibility modifier, then check for 'constructor'.
// All characters are consumed with skip() so nothing affects token boundaries.
static bool check_annotation_then_constructor(TSLexer *lexer) {
  // Skip one or more '@annotation' sequences
  while (lexer->lookahead == '@') {
    skip(lexer); // skip '@'
    if (!is_word_char(lexer->lookahead)) return false;
    // Read annotation name, including dot-separated qualifiers
    // (e.g. com.example.Inject)
    while (is_word_char(lexer->lookahead)) skip(lexer);
    while (lexer->lookahead == '.') {
      skip(lexer); // skip '.'
      if (!is_word_char(lexer->lookahead)) break;
      while (is_word_char(lexer->lookahead)) skip(lexer);
    }
    // Skip optional '(...)' argument list (handle nested parens and strings)
    if (lexer->lookahead == '(') {
      unsigned depth = 1;
      skip(lexer);
      while (depth > 0 && lexer->lookahead != '\0' && !lexer->eof(lexer)) {
        if (lexer->lookahead == '"') {
          // Skip over string literal to avoid miscounting parens inside strings
          skip(lexer);
          while (lexer->lookahead != '"' && lexer->lookahead != '\0' && !lexer->eof(lexer)) {
            if (lexer->lookahead == '\\') skip(lexer); // skip escaped char
            skip(lexer);
          }
          if (lexer->lookahead == '"') skip(lexer); // skip closing quote
        } else {
          if (lexer->lookahead == '(') depth++;
          else if (lexer->lookahead == ')') depth--;
          skip(lexer);
        }
      }
    }
    // Skip whitespace and newlines between annotations or before constructor
    while (iswspace(lexer->lookahead)) skip(lexer);
  }
  // Allow an optional visibility modifier before 'constructor'
  if (is_word_char(lexer->lookahead) && lexer->lookahead != 'c') {
    return check_modifier_then_constructor(lexer);
  }
  // Check directly for 'constructor'
  return check_word(lexer, "constructor", 11);
}

static bool scan_automatic_semicolon(TSLexer *lexer, const bool *valid_symbols) {
  lexer->result_symbol = AUTOMATIC_SEMICOLON;
  lexer->mark_end(lexer);

  bool sameline = true;
  for (;;) {
    if (lexer->eof(lexer)) return true;

    if (lexer->lookahead == ';') {
      advance(lexer);
      lexer->mark_end(lexer);
      return true;
    }

    if (!iswspace(lexer->lookahead)) break;

    if (lexer->lookahead == '\n') {
      skip(lexer);
      sameline = false;
      break;
    }

    if (lexer->lookahead == '\r') {
      skip(lexer);

      if (lexer->lookahead == '\n') skip(lexer);

      sameline = false;
      break;
    }

    skip(lexer);
  }

  // Skip whitespace and comments
  if (!scan_whitespace_and_comments(lexer))
    return false;

  if (sameline) {
    switch (lexer->lookahead) {
      // Insert imaginary semicolon before an 'import' but not in front
      // of other words or keywords starting with 'i'
      case 'i':
        return scan_for_word(lexer, "mport", 5);

      case ';':
        advance(lexer);
        lexer->mark_end(lexer);
        return true;

      // Don't insert a semicolon in other cases
      default:
        return false;
    }
  }

  switch (lexer->lookahead) {
      case ',':
      case '.':
      case ':':
      case '*':
      case '%':
      case '>':
      case '<':
      case '=':
      case '{':
      case '[':
      case '(':
      case '?':
      case '|':
      case '&':
        return false;

      // Handle `/` — could be division, line comment, or block comment.
      // For division: no ASI (continuation operator).
      // For line comments (`//`): skip the comment(s) and check the next
      // real token. If continuation, suppress ASI (return false — tree-sitter
      // resets, parses line_comment internally, then re-checks ASI).
      // If non-continuation, insert ASI (return true at original mark_end).
      // For block comments (`/*`): advance through the comment and produce
      // MULTILINE_COMMENT. The parser then re-calls the scanner for the ASI
      // decision on whatever token follows the comment.
      case '/': {
        advance(lexer);
        if (lexer->lookahead == '/') {
          // Line comment — skip to end of line using skip() since
          // line_comment is an internal token (the grammar handles it).
          skip(lexer);
          while (lexer->lookahead != '\n' && lexer->lookahead != '\r' &&
                 lexer->lookahead != 0 && !lexer->eof(lexer)) {
            skip(lexer);
          }
          // Skip any whitespace and further comments after this line comment.
          // A bare '/' (division) after comments is a continuation operator.
          if (!skip_whitespace_and_comments(lexer)) return false;
          // Now check the next real token.
          switch (lexer->lookahead) {
            case '.': case ',': case ':': case '*': case '%':
            case '>': case '<': case '=': case '{': case '[':
            case '(': case '?': case '|': case '&': case '/':
              return false;
            case '!':
              skip(lexer);
              if (lexer->lookahead == '=') return false;
              return true;
            case 'e':
              if (scan_for_word(lexer, "lse", 3)) {
                if (followed_by_arrow(lexer)) return true;
                return false;
              }
              return true;
            case 'a':
              if (scan_for_word(lexer, "s", 1)) return false;
              return true;
            case 'w':
              if (scan_for_word(lexer, "here", 4)) return false;
              return true;
            case 'c':
              if (scan_for_word(lexer, "atch", 4)) return false;
              return true;
            case 'b':
              if (valid_symbols[BY_DELEGATION_HINT] &&
                  scan_for_word(lexer, "y", 1)) return false;
              return true;
            case 'f':
              if (scan_for_word(lexer, "inally", 6)) return false;
              return true;
            default:
              return true;
          }
        } else if (lexer->lookahead == '*') {
          // Block comment after a newline. Use advance() to read through the
          // comment so the content is available for MULTILINE_COMMENT if we
          // decide to produce it. DON'T call mark_end yet — we defer that
          // decision until we know what follows the comment.
          advance(lexer);
          unsigned nesting_depth = 1;
          bool after_star = false;
          while (nesting_depth > 0 && !lexer->eof(lexer)) {
            switch (lexer->lookahead) {
              case '*':
                advance(lexer);
                after_star = true;
                break;
              case '/':
                advance(lexer);
                if (after_star) {
                  after_star = false;
                  nesting_depth--;
                } else {
                  if (lexer->lookahead == '*') {
                    nesting_depth++;
                    advance(lexer);
                  }
                  after_star = false;
                }
                break;
              case '\0':
                if (lexer->eof(lexer)) {
                  // Unterminated block comment at EOF — produce it.
                  lexer->result_symbol = MULTILINE_COMMENT;
                  lexer->mark_end(lexer);
                  return true;
                }
                // fallthrough
              default:
                advance(lexer);
                after_star = false;
                break;
            }
          }
          // Skip whitespace after the block comment. Don't skip further
          // comments — the continuation switch handles '/' and '*', so
          // subsequent comments will be correctly treated as continuation.
          // Skipping them here would swallow them (they'd never appear
          // as separate tokens in the parse tree).
          while (iswspace(lexer->lookahead)) skip(lexer);
          // Check the next real token to decide: MULTILINE_COMMENT or ASI?
          //
          // IMPORTANT: For keyword checks (else, as, where, !=), we must
          // call mark_end BEFORE scan_for_word/skip, because those functions
          // advance the cursor past the keyword. If mark_end were called
          // after, the MULTILINE_COMMENT span would swallow the keyword
          // and the parser would never see it.
          switch (lexer->lookahead) {
            case '.': case ',': case ':': case '%':
            case '>': case '<': case '=': case '{': case '[':
            case '(': case '?': case '|': case '&': case '/':
            case '*':
              // Continuation operator — produce MULTILINE_COMMENT.
              lexer->mark_end(lexer);
              lexer->result_symbol = MULTILINE_COMMENT;
              return true;
            case '!':
              // mark_end before consuming '!' so it's not swallowed.
              lexer->mark_end(lexer);
              skip(lexer);
              if (lexer->lookahead == '=') {
                // != is continuation — produce MULTILINE_COMMENT.
                lexer->result_symbol = MULTILINE_COMMENT;
                return true;
              }
              // Unary ! — not continuation. Produce ASI at original
              // position (mark_end was at P0 before, now at '!' position,
              // but the token has no advance()d content past the comment,
              // so tree-sitter will re-scan from here).
              return true;
            case 'e':
              lexer->mark_end(lexer);
              if (scan_for_word(lexer, "lse", 3)) {
                if (followed_by_arrow(lexer)) return true;
                lexer->result_symbol = MULTILINE_COMMENT;
                return true;
              }
              return true;
            case 'a':
              lexer->mark_end(lexer);
              if (scan_for_word(lexer, "s", 1)) {
                lexer->result_symbol = MULTILINE_COMMENT;
                return true;
              }
              return true;
            case 'w':
              lexer->mark_end(lexer);
              if (scan_for_word(lexer, "here", 4)) {
                lexer->result_symbol = MULTILINE_COMMENT;
                return true;
              }
              return true;
            case 'b':
              if (valid_symbols[BY_DELEGATION_HINT]) {
                lexer->mark_end(lexer);
                if (scan_for_word(lexer, "y", 1)) {
                  lexer->result_symbol = MULTILINE_COMMENT;
                  return true;
                }
              }
              return true;
            default:
              // the original position (P0, before the comment), so the
              // ASI token is zero-width. The block comment will be
              // re-scanned as MULTILINE_COMMENT on the next parse step.
              return true;
          }
        }
        // Bare `/` (not `//` or `/*`) — division. No ASI.
        return false;
      }

      // In Kotlin, `+` and `-` after a newline are always prefix operators,
      // not binary continuation. If a binary operation is intended, the
      // operator must be placed at the end of the previous line:
      //   a +       // binary: a + b
      //     b
      //   a         // prefix: a; +b
      //   + b
      // The grammar ensures AUTOMATIC_SEMICOLON is only valid where a
      // statement could end, so this won't fire inside () or [] where
      // newlines don't terminate statements.
      case '+':
      case '-':
        return true;

      // Don't insert a semicolon before `!=`, but do insert one before a unary `!`.
      case '!':
        skip(lexer);
        return lexer->lookahead != '=';

      // Don't insert a semicolon before 'by' in delegation contexts.
      // Gated on BY_DELEGATION_HINT so `by` remains a usable soft-keyword
      // identifier in non-delegation positions.
      case 'b':
        return !(valid_symbols[BY_DELEGATION_HINT] &&
                 scan_for_word(lexer, "y", 1));

      // Don't insert a semicolon before an else, unless it's
      // followed by "->" (a when-entry's else, not an if-else).
      case 'e':
        if (!scan_for_word(lexer, "lse", 3)) return true;
        return followed_by_arrow(lexer);

      // Don't insert a semicolon before an as
      case 'a':
        return !scan_for_word(lexer, "s", 1);

      // Don't insert a semicolon before a where
      case 'w':
        return !scan_for_word(lexer, "here", 4);

      // Don't insert a semicolon before `instanceof`, or before `internal`
      // when followed by `constructor` in a class declaration context.
      case 'i':
        if (valid_symbols[PRIMARY_CONSTRUCTOR_KEYWORD] &&
            !valid_symbols[STRING_CONTENT] &&
            check_modifier_then_constructor(lexer)) {
          return false;
        }
        // Note: lexer has advanced past the word. For "instanceof", scan_for_word
        // can no longer match. But since "instanceof" is not a Kotlin keyword
        // (Kotlin uses "is"), this is acceptable — ASI is inserted, which is
        // the correct behavior for any non-constructor identifier.
        return true;

      // Don't insert a semicolon before `public/private/protected constructor`
      // in class declaration context.
      case 'p':
        if (valid_symbols[PRIMARY_CONSTRUCTOR_KEYWORD] &&
            !valid_symbols[STRING_CONTENT] &&
            check_modifier_then_constructor(lexer)) {
          return false;
        }
        return true;

      // Don't insert a semicolon before `constructor` if the parser expects
      // a primary constructor (class declaration context). In class body
      // context, PRIMARY_CONSTRUCTOR_KEYWORD won't be valid, so ASI is
      // inserted normally before secondary constructors.
      // Guard against error recovery mode where all symbols are valid.
      // Instead of suppressing ASI, we emit the constructor keyword directly
      // since it's an external token and the internal lexer won't match it.
      case 'c':
        if (valid_symbols[PRIMARY_CONSTRUCTOR_KEYWORD] &&
            !valid_symbols[STRING_CONTENT]) {
          const char *kw = "constructor";
          bool matched = true;
          for (unsigned i = 0; i < 11; i++) {
            if (lexer->lookahead != kw[i]) { matched = false; break; }
            advance(lexer);
          }
          if (matched && !is_word_char(lexer->lookahead)) {
            lexer->result_symbol = PRIMARY_CONSTRUCTOR_KEYWORD;
            lexer->mark_end(lexer);
            return true;
          }
          // If constructor didn't match, we've advanced past some chars.
          // Can't reliably check 'catch' now. Just insert ASI.
          return true;
        }
        // Not in constructor context — check for 'catch'
        return !scan_for_word(lexer, "atch", 4);

      // Don't insert a semicolon before finally (continues try_expression)
      case 'f':
        return !scan_for_word(lexer, "inally", 6);

      // Don't insert a semicolon before an annotation that precedes 'constructor'
      // e.g. `class Foo\n@Bar\nconstructor(...)` — the @Bar is a constructor modifier
      case '@':
        if (valid_symbols[PRIMARY_CONSTRUCTOR_KEYWORD] &&
            !valid_symbols[STRING_CONTENT] &&
            check_annotation_then_constructor(lexer)) {
          return false;
        }
        return true;

      case ';':
        advance(lexer);
        lexer->mark_end(lexer);
        return true;

      default:
        return true;
  }
}


// Scan a dot in import identifiers. Matches '.' normally, but when the dot
// is followed by a newline and then the 'import' keyword, produces an
// AUTOMATIC_SEMICOLON (zero-width, before the dot) instead. This cleanly
// terminates the current import_header, preventing malformed imports
// (e.g. trailing dots) from bleeding into subsequent valid imports.
static bool scan_import_dot(TSLexer *lexer) {
  if (lexer->lookahead != '.') return false;

  // Mark end BEFORE consuming the dot — this is where ASI would go
  lexer->mark_end(lexer);

  advance(lexer);

  // Peek ahead: skip horizontal whitespace, check for newline
  bool found_newline = false;
  while (iswspace(lexer->lookahead)) {
    if (lexer->lookahead == '\n' || lexer->lookahead == '\r') {
      found_newline = true;
    }
    skip(lexer);
  }

  if (found_newline && lexer->lookahead == 'i' &&
      scan_for_word(lexer, "mport", 5)) {
    // Trailing dot followed by 'import' on next line — produce ASI
    // instead of the dot. mark_end was set before the dot, so the
    // semicolon is zero-width at that position.
    lexer->result_symbol = AUTOMATIC_SEMICOLON;
    return true;
  }

  // Normal dot — include it in the token
  lexer->result_symbol = IMPORT_DOT;
  lexer->mark_end(lexer);
  return true;
}

bool tree_sitter_kotlin_external_scanner_scan(void *payload, TSLexer *lexer, const bool *valid_symbols) {
  // BY_DELEGATION_HINT is declared in the grammar (optional, before `by` in
  // explicit_delegation and property_delegate) purely so it appears in
  // valid_symbols when the parser is in a delegation context. The scanner
  // never emits it; it's used only as a context flag in scan_automatic_semicolon.
  if (valid_symbols[AUTOMATIC_SEMICOLON]) {
    bool ret = scan_automatic_semicolon(lexer, valid_symbols);
    // if we fail to find an automatic semicolon, it's still possible that we may
    // want to lex a string or comment later
    if (ret) return ret;
  }

  // Match dots in import identifiers, refusing dots that would cause
  // malformed imports to bleed into subsequent import statements.
  if (valid_symbols[IMPORT_DOT]) {
    if (scan_import_dot(lexer)) return true;
  }

  // Match 'constructor' keyword for primary constructors when on the same line
  // (the cross-newline case is handled inside scan_automatic_semicolon)
  if (valid_symbols[PRIMARY_CONSTRUCTOR_KEYWORD] && !valid_symbols[STRING_CONTENT]) {
    while (iswspace(lexer->lookahead)) skip(lexer);
    if (lexer->lookahead == 'c') {
      const char *kw = "constructor";
      bool matched = true;
      for (unsigned i = 0; i < 11; i++) {
        if (lexer->lookahead != kw[i]) { matched = false; break; }
        advance(lexer);
      }
      if (matched && !is_word_char(lexer->lookahead)) {
        lexer->result_symbol = PRIMARY_CONSTRUCTOR_KEYWORD;
        lexer->mark_end(lexer);
        return true;
      }
    }
  }

  // content, end, or interpolation start
  if (valid_symbols[STRING_CONTENT] || valid_symbols[INTERPOLATION_EXPRESSION_START] ||
      valid_symbols[INTERPOLATION_IDENTIFIER_START]) {
    if (scan_string_content(lexer, payload, valid_symbols)) return true;
  }

  // a string might follow after some whitespace, so we can't lookahead
  // until we get rid of it
  while (iswspace(lexer->lookahead)) skip(lexer);

  if (valid_symbols[STRING_START] && scan_string_start(lexer, payload)) {
    lexer->result_symbol = STRING_START;
    return true;
  }

  if (valid_symbols[MULTILINE_COMMENT] && scan_multiline_comment(lexer)) {
    return true;
  }

  return false;
}

void *tree_sitter_kotlin_external_scanner_create() {
  Stack *stack = ts_calloc(1, sizeof(Stack));
  if (stack == NULL) abort();
  array_init(stack);
  return stack;
}

void tree_sitter_kotlin_external_scanner_destroy(void *payload) {
  Stack *stack = (Stack *)payload;
  array_delete(stack);
  ts_free(stack);
}

unsigned tree_sitter_kotlin_external_scanner_serialize(void *payload, char *buffer) {
  Stack *stack = (Stack *)payload;
  unsigned n = stack->size;
  if (n > TREE_SITTER_SERIALIZATION_BUFFER_SIZE) {
    n = TREE_SITTER_SERIALIZATION_BUFFER_SIZE;
  }
  if (n > 0) {
    // it's an undefined behavior to memcpy 0 bytes
    memcpy(buffer, stack->contents, n);
  }
  return n;
}

void tree_sitter_kotlin_external_scanner_deserialize(void *payload, const char *buffer, unsigned length) {
  Stack *stack = (Stack *)payload;
  // Stack entries are 2 bytes each (delimiter + prefix_len).
  // Discard corrupted state with odd length.
  if (length > 0 && length % 2 == 0) {
    array_reserve(stack, length);
    memcpy(stack->contents, buffer, length);
    stack->size = length;
  } else {
    array_clear(stack);
  }
}

#include "tree_sitter/parser.h"
#include <string.h>
#include <wctype.h>

#define TOKEN_COUNT 34

enum TokenType {
    BLOCK_COMMENT,
    RAW_STR_PART,
    RAW_STR_CONTINUING_INDICATOR,
    RAW_STR_END_PART,
    IMPLICIT_SEMI,
    EXPLICIT_SEMI,
    ARROW_OPERATOR,
    DOT_OPERATOR,
    CONJUNCTION_OPERATOR,
    DISJUNCTION_OPERATOR,
    NIL_COALESCING_OPERATOR,
    DOUBLE_OPTIONAL,
    EQUAL_SIGN,
    EQ_EQ,
    PLUS_THEN_WS,
    MINUS_THEN_WS,
    BANG,
    THROWS_KEYWORD,
    RETHROWS_KEYWORD,
    DEFAULT_KEYWORD,
    WHERE_KEYWORD,
    ELSE_KEYWORD,
    CATCH_KEYWORD,
    AS_KEYWORD,
    AS_QUEST,
    AS_BANG,
    ASYNC_KEYWORD,
    CUSTOM_OPERATOR,
    HASH_SYMBOL,
    DIRECTIVE_IF,
    DIRECTIVE_ELSEIF,
    DIRECTIVE_ELSE,
    DIRECTIVE_ENDIF,
    FAKE_TRY_BANG
};

#define OPERATOR_COUNT 20

/// Identifies fixed operators by their position in the shared lookup tables.
enum OperatorIndex {
    /// Identifies the arrow operator.
    OPERATOR_INDEX_ARROW,
    /// Identifies the dot operator.
    OPERATOR_INDEX_DOT,
    /// Identifies the conjunction operator.
    OPERATOR_INDEX_CONJUNCTION,
    /// Identifies the disjunction operator.
    OPERATOR_INDEX_DISJUNCTION,
    /// Identifies the nil-coalescing operator.
    OPERATOR_INDEX_NIL_COALESCING,
    /// Identifies the assignment operator.
    OPERATOR_INDEX_EQUAL_SIGN,
    /// Identifies the equality operator.
    OPERATOR_INDEX_EQUALITY,
    /// Identifies the whitespace-sensitive plus operator.
    OPERATOR_INDEX_PLUS_THEN_WHITESPACE,
    /// Identifies the whitespace-sensitive minus operator.
    OPERATOR_INDEX_MINUS_THEN_WHITESPACE,
    /// Identifies the bang operator.
    OPERATOR_INDEX_BANG,
    /// Identifies the throws keyword.
    OPERATOR_INDEX_THROWS,
    /// Identifies the rethrows keyword.
    OPERATOR_INDEX_RETHROWS,
    /// Identifies the default keyword.
    OPERATOR_INDEX_DEFAULT,
    /// Identifies the where keyword.
    OPERATOR_INDEX_WHERE,
    /// Identifies the else keyword.
    OPERATOR_INDEX_ELSE,
    /// Identifies the catch keyword.
    OPERATOR_INDEX_CATCH,
    /// Identifies the as keyword.
    OPERATOR_INDEX_AS,
    /// Identifies the conditional cast operator.
    OPERATOR_INDEX_AS_QUESTION,
    /// Identifies the forced cast operator.
    OPERATOR_INDEX_AS_BANG,
    /// Identifies the async keyword.
    OPERATOR_INDEX_ASYNC
};

const char* OPERATORS[OPERATOR_COUNT] = {
    "->",
    ".",
    "&&",
    "||",
    "??",
    "=",
    "==",
    "+",
    "-",
    "!",
    "throws",
    "rethrows",
    "default",
    "where",
    "else",
    "catch",
    "as",
    "as?",
    "as!",
    "async"
};

enum IllegalTerminatorGroup {
    ALPHANUMERIC,
    OPERATOR_SYMBOLS,
    OPERATOR_OR_DOT,
    NON_WHITESPACE
};

const enum IllegalTerminatorGroup OP_ILLEGAL_TERMINATORS[OPERATOR_COUNT] = {
    OPERATOR_SYMBOLS, // ->
    OPERATOR_OR_DOT,  // .
    OPERATOR_SYMBOLS, // &&
    OPERATOR_SYMBOLS, // ||
    OPERATOR_SYMBOLS, // ??
    OPERATOR_SYMBOLS, // =
    OPERATOR_SYMBOLS, // ==
    NON_WHITESPACE,   // +
    NON_WHITESPACE,   // -
    OPERATOR_SYMBOLS, // !
    ALPHANUMERIC,     // throws
    ALPHANUMERIC,     // rethrows
    ALPHANUMERIC,     // default
    ALPHANUMERIC,     // where
    ALPHANUMERIC,     // else
    ALPHANUMERIC,     // catch
    ALPHANUMERIC,     // as
    OPERATOR_SYMBOLS, // as?
    OPERATOR_SYMBOLS, // as!
    ALPHANUMERIC      // async
};

const enum TokenType OP_SYMBOLS[OPERATOR_COUNT] = {
    ARROW_OPERATOR,
    DOT_OPERATOR,
    CONJUNCTION_OPERATOR,
    DISJUNCTION_OPERATOR,
    NIL_COALESCING_OPERATOR,
    EQUAL_SIGN,
    EQ_EQ,
    PLUS_THEN_WS,
    MINUS_THEN_WS,
    BANG,
    THROWS_KEYWORD,
    RETHROWS_KEYWORD,
    DEFAULT_KEYWORD,
    WHERE_KEYWORD,
    ELSE_KEYWORD,
    CATCH_KEYWORD,
    AS_KEYWORD,
    AS_QUEST,
    AS_BANG,
    ASYNC_KEYWORD
};

const uint64_t OP_SYMBOL_SUPPRESSOR[OPERATOR_COUNT] = {
    0, // ARROW_OPERATOR,
    0, // DOT_OPERATOR,
    0, // CONJUNCTION_OPERATOR,
    0, // DISJUNCTION_OPERATOR,
    0, // NIL_COALESCING_OPERATOR,
    0, // EQUAL_SIGN,
    0, // EQ_EQ,
    0, // PLUS_THEN_WS,
    0, // MINUS_THEN_WS,
    1ULL << FAKE_TRY_BANG, // BANG,
        0, // THROWS_KEYWORD,
        0, // RETHROWS_KEYWORD,
        0, // DEFAULT_KEYWORD,
        0, // WHERE_KEYWORD,
        0, // ELSE_KEYWORD,
        0, // CATCH_KEYWORD,
        0, // AS_KEYWORD,
        0, // AS_QUEST,
        0, // AS_BANG,
        0, // ASYNC_KEYWORD
};

#define RESERVED_OP_COUNT 31

const char* RESERVED_OPS[RESERVED_OP_COUNT] = {
    "/",
    "=",
    "-",
    "+",
    "!",
    "*",
    "%",
    "<",
    ">",
    "&",
    "|",
    "^",
    "?",
    "~",
    ".",
    "..",
    "->",
    "/*",
    "*/",
    "+=",
    "-=",
    "*=",
    "/=",
    "%=",
    ">>",
    "<<",
    "++",
    "--",
    "===",
    "...",
    "..<"
};

static bool is_cross_semi_token(enum TokenType op) {
    switch(op) {
    case ARROW_OPERATOR:
    case DOT_OPERATOR:
    case EQUAL_SIGN:
    case EQ_EQ:
    case PLUS_THEN_WS:
    case MINUS_THEN_WS:
    case THROWS_KEYWORD:
    case RETHROWS_KEYWORD:
    case DEFAULT_KEYWORD:
    case WHERE_KEYWORD:
    case ELSE_KEYWORD:
    case CATCH_KEYWORD:
    case AS_KEYWORD:
    case AS_QUEST:
    case AS_BANG:
    case ASYNC_KEYWORD:
    case CUSTOM_OPERATOR:
        return true;
    case BANG:
    default:
        return false;
    }
}

#define NON_CONSUMING_CROSS_SEMI_CHAR_COUNT 8
const uint32_t NON_CONSUMING_CROSS_SEMI_CHARS[NON_CONSUMING_CROSS_SEMI_CHAR_COUNT] = {
    '?', ':', '{', '&', '|', '^', '<', '>'
};

/**
 * All possible results of having performed some sort of parsing.
 *
 * A parser can return a result along two dimensions:
 * 1. Should the scanner continue trying to find another result?
 * 2. Was some result produced by this parsing attempt?
 *
 * These are flattened into a single enum together. When the function returns one of the `TOKEN_FOUND` cases, it
 * will always populate its `symbol_result` field. When it returns one of the `STOP_PARSING` cases, callers should
 * immediately return (with the value, if there is one).
 */
enum ParseDirective {
    CONTINUE_PARSING_NOTHING_FOUND,
    CONTINUE_PARSING_TOKEN_FOUND,
    CONTINUE_PARSING_SLASH_CONSUMED,
    STOP_PARSING_NOTHING_FOUND,
    STOP_PARSING_TOKEN_FOUND,
    STOP_PARSING_END_OF_FILE
};

struct ScannerState {
    uint32_t ongoing_raw_str_hash_count;
};

void *tree_sitter_swift_external_scanner_create() {
    return calloc(1, sizeof(struct ScannerState));
}

void tree_sitter_swift_external_scanner_destroy(void *payload) {
    free(payload);
}

void tree_sitter_swift_external_scanner_reset(void *payload) {
    struct ScannerState *state = (struct ScannerState *)payload;
    state->ongoing_raw_str_hash_count = 0;
}

unsigned tree_sitter_swift_external_scanner_serialize(void *payload, char *buffer) {
    struct ScannerState *state = (struct ScannerState *)payload;
    uint32_t hash_count = state->ongoing_raw_str_hash_count;
    buffer[0] = (hash_count >> 24) & 0xff;
    buffer[1] = (hash_count >> 16) & 0xff;
    buffer[2] = (hash_count >> 8) & 0xff;
    buffer[3] = (hash_count) & 0xff;
    return 4;
}

void tree_sitter_swift_external_scanner_deserialize(
    void *payload,
    const char *buffer,
    unsigned length
) {
    if (length < 4) {
        return;
    }

    uint32_t hash_count = (
                              (((uint32_t) buffer[0]) << 24) |
                              (((uint32_t) buffer[1]) << 16) |
                              (((uint32_t) buffer[2]) << 8) |
                              (((uint32_t) buffer[3]))
                          );
    struct ScannerState *state = (struct ScannerState *)payload;
    state->ongoing_raw_str_hash_count = hash_count;
}

static void advance(TSLexer *lexer) {
    lexer->advance(lexer, false);
}

static bool should_treat_as_wspace(int32_t character) {
    return iswspace(character) || (((int32_t) ';') == character);
}

static bool any_reserved_ops(uint8_t *encountered_reserved_ops) {
    for (int op_idx = 0; op_idx < RESERVED_OP_COUNT; op_idx++) {
        if (encountered_reserved_ops[op_idx] == 2) {
            return true;
        }
    }

    return false;
}

static bool is_legal_custom_operator(
    int32_t char_idx,
    int32_t first_char,
    int32_t cur_char
) {
    bool is_first_char = !char_idx;
    switch (cur_char) {
    case '=':
    case '-':
    case '+':
    case '!':
    case '%':
    case '<':
    case '>':
    case '&':
    case '|':
    case '^':
    case '?':
    case '~':
        return true;
    case '.':
        // Grammar allows `.` for any operator that starts with `.`
        return is_first_char || first_char == '.';
    case '*':
    case '/':
        // Not listed in the grammar, but `/*` and `//` can't be the start of an operator since they start comments
        return char_idx != 1 || first_char != '/';
    default:
        if (
            (cur_char >= 0x00A1 && cur_char <= 0x00A7) ||
            (cur_char == 0x00A9) ||
            (cur_char == 0x00AB) ||
            (cur_char == 0x00AC) ||
            (cur_char == 0x00AE) ||
            (cur_char >= 0x00B0 && cur_char <= 0x00B1) ||
            (cur_char == 0x00B6) ||
            (cur_char == 0x00BB) ||
            (cur_char == 0x00BF) ||
            (cur_char == 0x00D7) ||
            (cur_char == 0x00F7) ||
            (cur_char >= 0x2016 && cur_char <= 0x2017) ||
            (cur_char >= 0x2020 && cur_char <= 0x2027) ||
            (cur_char >= 0x2030 && cur_char <= 0x203E) ||
            (cur_char >= 0x2041 && cur_char <= 0x2053) ||
            (cur_char >= 0x2055 && cur_char <= 0x205E) ||
            (cur_char >= 0x2190 && cur_char <= 0x23FF) ||
            (cur_char >= 0x2500 && cur_char <= 0x2775) ||
            (cur_char >= 0x2794 && cur_char <= 0x2BFF) ||
            (cur_char >= 0x2E00 && cur_char <= 0x2E7F) ||
            (cur_char >= 0x3001 && cur_char <= 0x3003) ||
            (cur_char >= 0x3008 && cur_char <= 0x3020) ||
            (cur_char == 0x3030)
        ) {
            return true;
        } else if (
            (cur_char >= 0x0300 && cur_char <= 0x036f) ||
            (cur_char >= 0x1DC0 && cur_char <= 0x1DFF) ||
            (cur_char >= 0x20D0 && cur_char <= 0x20FF) ||
            (cur_char >= 0xFE00 && cur_char <= 0xFE0F) ||
            (cur_char >= 0xFE20 && cur_char <= 0xFE2F) ||
            (cur_char >= 0xE0100 && cur_char <= 0xE01EF)
        ) {
            return !is_first_char;
        } else {
            return false;
        }
    }
}

/// Collects valid fixed operators that can begin with the character.
static uint32_t collect_fixed_operator_candidates(
    int32_t character,
    const bool *valid_symbols,
    uint8_t *candidates
) {
    uint32_t count = 0;
    switch (character) {
    case '-':
        if (valid_symbols[ARROW_OPERATOR]) {
            candidates[count++] = OPERATOR_INDEX_ARROW;
        }
        if (valid_symbols[MINUS_THEN_WS]) {
            candidates[count++] = OPERATOR_INDEX_MINUS_THEN_WHITESPACE;
        }
        break;
    case '.':
        if (valid_symbols[DOT_OPERATOR]) {
            candidates[count++] = OPERATOR_INDEX_DOT;
        }
        break;
    case '&':
        if (valid_symbols[CONJUNCTION_OPERATOR]) {
            candidates[count++] = OPERATOR_INDEX_CONJUNCTION;
        }
        break;
    case '|':
        if (valid_symbols[DISJUNCTION_OPERATOR]) {
            candidates[count++] = OPERATOR_INDEX_DISJUNCTION;
        }
        break;
    case '?':
        if (
            valid_symbols[NIL_COALESCING_OPERATOR] ||
            valid_symbols[DOUBLE_OPTIONAL]
        ) {
            candidates[count++] = OPERATOR_INDEX_NIL_COALESCING;
        }
        break;
    case '=':
        if (valid_symbols[EQUAL_SIGN]) {
            candidates[count++] = OPERATOR_INDEX_EQUAL_SIGN;
        }
        if (valid_symbols[EQ_EQ]) {
            candidates[count++] = OPERATOR_INDEX_EQUALITY;
        }
        break;
    case '+':
        if (valid_symbols[PLUS_THEN_WS]) {
            candidates[count++] = OPERATOR_INDEX_PLUS_THEN_WHITESPACE;
        }
        break;
    case '!':
        if (valid_symbols[BANG]) {
            candidates[count++] = OPERATOR_INDEX_BANG;
        }
        break;
    case 't':
        if (valid_symbols[THROWS_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_THROWS;
        }
        break;
    case 'r':
        if (valid_symbols[RETHROWS_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_RETHROWS;
        }
        break;
    case 'd':
        if (valid_symbols[DEFAULT_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_DEFAULT;
        }
        break;
    case 'w':
        if (valid_symbols[WHERE_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_WHERE;
        }
        break;
    case 'e':
        if (valid_symbols[ELSE_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_ELSE;
        }
        break;
    case 'c':
        if (valid_symbols[CATCH_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_CATCH;
        }
        break;
    case 'a':
        if (valid_symbols[AS_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_AS;
        }
        if (valid_symbols[AS_QUEST]) {
            candidates[count++] = OPERATOR_INDEX_AS_QUESTION;
        }
        if (valid_symbols[AS_BANG]) {
            candidates[count++] = OPERATOR_INDEX_AS_BANG;
        }
        if (valid_symbols[ASYNC_KEYWORD]) {
            candidates[count++] = OPERATOR_INDEX_ASYNC;
        }
        break;
    default:
        break;
    }
    return count;
}

static bool eat_operators(
    TSLexer *lexer,
    const bool *valid_symbols,
    bool mark_end,
    bool token_is_immediate,
    const int32_t prior_char,
    enum TokenType *symbol_result
) {
    int32_t first_char = prior_char ? prior_char : lexer->lookahead;
    bool possible_custom_operator = valid_symbols[CUSTOM_OPERATOR] &&
                                    is_legal_custom_operator(0, first_char, first_char);
    uint8_t possible_operators[4];
    uint32_t possible_operator_count = collect_fixed_operator_candidates(
                                           first_char,
                                           valid_symbols,
                                           possible_operators
                                       );
    if (possible_operator_count == 0 && !possible_custom_operator) {
        return false;
    }

    uint8_t reserved_operators[RESERVED_OP_COUNT];
    if (possible_custom_operator) {
        for (int op_idx = 0; op_idx < RESERVED_OP_COUNT; op_idx++) {
            reserved_operators[op_idx] = RESERVED_OPS[op_idx][0] == first_char;
        }
    }

    int32_t last_examined_char = first_char;

    int32_t str_idx = prior_char ? 1 : 0;
    int32_t full_match = -1;
    while(true) {
        uint32_t candidate_idx = 0;
        while (candidate_idx < possible_operator_count) {
            int op_idx = possible_operators[candidate_idx];

            if (OPERATORS[op_idx][str_idx] == '\0') {
                // Make sure that the operator is allowed to have the next character as its lookahead.
                enum IllegalTerminatorGroup illegal_terminators = OP_ILLEGAL_TERMINATORS[op_idx];
                switch (lexer->lookahead) {
                // See "Operators":
                // https://docs.swift.org/swift-book/ReferenceManual/LexicalStructure.html#ID418
                case '/':
                case '=':
                case '-':
                case '+':
                case '!':
                case '*':
                case '%':
                case '<':
                case '>':
                case '&':
                case '|':
                case '^':
                case '?':
                case '~':
                    if (illegal_terminators == OPERATOR_SYMBOLS) {
                        break;
                    } // Otherwise, intentionally fall through to the OPERATOR_OR_DOT case
                // fall through
                case '.':
                    if (illegal_terminators == OPERATOR_OR_DOT) {
                        break;
                    } // Otherwise, fall through to DEFAULT which checks its groups directly
                // fall through
                default:
                    if (iswalnum(lexer->lookahead) && illegal_terminators == ALPHANUMERIC) {
                        break;
                    }

                    if (!iswspace(lexer->lookahead) && illegal_terminators == NON_WHITESPACE) {
                        break;
                    }

                    full_match = op_idx;
                    if (mark_end) {
                        lexer->mark_end(lexer);
                    }
                }

                possible_operator_count -= 1;
                possible_operators[candidate_idx] = possible_operators[possible_operator_count];
                continue;
            }

            if (OPERATORS[op_idx][str_idx] != lexer->lookahead) {
                possible_operator_count -= 1;
                possible_operators[candidate_idx] = possible_operators[possible_operator_count];
                continue;
            }

            candidate_idx += 1;
        }

        if (possible_custom_operator) {
            for (int op_idx = 0; op_idx < RESERVED_OP_COUNT; op_idx++) {
                if (!reserved_operators[op_idx]) {
                    continue;
                }

                if (RESERVED_OPS[op_idx][str_idx] == '\0') {
                    reserved_operators[op_idx] = 0;
                    continue;
                }

                if (RESERVED_OPS[op_idx][str_idx] != lexer->lookahead) {
                    reserved_operators[op_idx] = 0;
                    continue;
                }

                if (RESERVED_OPS[op_idx][str_idx + 1] == '\0') {
                    reserved_operators[op_idx] = 2;
                    continue;
                }
            }
        }

        possible_custom_operator = possible_custom_operator && is_legal_custom_operator(
                                       str_idx,
                                       first_char,
                                       lexer->lookahead
                                   );

        uint32_t encountered_ops = possible_operator_count;
        if (encountered_ops == 0) {
            if (!possible_custom_operator) {
                break;
            } else if (mark_end && full_match == -1) {
                lexer->mark_end(lexer);
            }
        }

        last_examined_char = lexer->lookahead;
        lexer->advance(lexer, false);
        str_idx += 1;

        if (encountered_ops == 0 && !is_legal_custom_operator(
                    str_idx,
                    first_char,
                    lexer->lookahead
                )) {
            break;
        }
    }

    if (full_match != -1) {
        // We have a match -- first see if that match has a symbol that suppresses it. For example, in `try!`, we do not
        // want to emit the `!` as a symbol in our scanner, because we want the parser to have the chance to parse it as
        // an immediate token.
        uint64_t suppressing_symbols = OP_SYMBOL_SUPPRESSOR[full_match];
        if (suppressing_symbols) {
            for (uint64_t suppressor = 0; suppressor < TOKEN_COUNT; suppressor++) {
                if (!(suppressing_symbols & 1ULL << suppressor)) {
                    continue;
                }

                // The suppressing symbol is valid in this position, so skip it.
                if (valid_symbols[suppressor]) {
                    return false;
                }
            }
        }
        enum TokenType matched_symbol = OP_SYMBOLS[full_match];
        if (
            matched_symbol == NIL_COALESCING_OPERATOR &&
            valid_symbols[DOUBLE_OPTIONAL]
        ) {
            if (!token_is_immediate && !valid_symbols[NIL_COALESCING_OPERATOR]) {
                return false;
            }
            matched_symbol = token_is_immediate
                             ? DOUBLE_OPTIONAL
                             : NIL_COALESCING_OPERATOR;
        }
        *symbol_result = matched_symbol;
        return true;
    }

    if (possible_custom_operator && !any_reserved_ops(reserved_operators)) {
        if ((last_examined_char != '<' || iswspace(lexer->lookahead)) && mark_end) {
            lexer->mark_end(lexer);
        }
        *symbol_result = CUSTOM_OPERATOR;
        return true;
    }

    return false;
}

static enum ParseDirective eat_comment(
    TSLexer *lexer,
    const bool *valid_symbols,
    bool mark_end,
    enum TokenType *symbol_result
) {
    if (lexer->lookahead != '/') {
        return CONTINUE_PARSING_NOTHING_FOUND;
    }

    advance(lexer);

    if (lexer->lookahead != '*') {
        return CONTINUE_PARSING_SLASH_CONSUMED;
    }

    advance(lexer);

    bool after_star = false;
    unsigned nesting_depth = 1;
    for (;;) {
        switch (lexer->lookahead) {
        case '\0':
            return STOP_PARSING_END_OF_FILE;
        case '*':
            advance(lexer);
            after_star = true;
            break;
        case '/':
            if (after_star) {
                advance(lexer);
                after_star = false;
                nesting_depth--;
                if (nesting_depth == 0) {
                    if (mark_end) {
                        lexer->mark_end(lexer);
                    }
                    *symbol_result = BLOCK_COMMENT;
                    return STOP_PARSING_TOKEN_FOUND;
                }
            } else {
                advance(lexer);
                after_star = false;
                if (lexer->lookahead == '*') {
                    nesting_depth++;
                    advance(lexer);
                }
            }
            break;
        default:
            advance(lexer);
            after_star = false;
            break;
        }
    }
}

static enum ParseDirective eat_whitespace(
    TSLexer *lexer,
    const bool *valid_symbols,
    enum TokenType *symbol_result
) {
    enum ParseDirective ws_directive = CONTINUE_PARSING_NOTHING_FOUND;
    bool semi_is_valid = valid_symbols[IMPLICIT_SEMI] && valid_symbols[EXPLICIT_SEMI];
    uint32_t lookahead;
    while (should_treat_as_wspace(lookahead = lexer->lookahead)) {
        if (lookahead == ';') {
            if (semi_is_valid) {
                ws_directive = STOP_PARSING_TOKEN_FOUND;
                lexer->advance(lexer, false);
            }

            break;
        }

        lexer->advance(lexer, true);

        lexer->mark_end(lexer);

        if (ws_directive == CONTINUE_PARSING_NOTHING_FOUND && (lookahead == '\n' || lookahead == '\r')) {
            ws_directive = CONTINUE_PARSING_TOKEN_FOUND;
        }
    }

    enum ParseDirective any_comment = CONTINUE_PARSING_NOTHING_FOUND;
    if (ws_directive == CONTINUE_PARSING_TOKEN_FOUND && lookahead == '/') {
        bool has_seen_single_comment = false;
        while (lexer->lookahead == '/') {
            // It's possible that this is a comment - start an exploratory mission to find out, and if it is, look for what
            // comes after it. We care about what comes after it for the purpose of suppressing the newline.

            enum TokenType multiline_comment_result;
            any_comment = eat_comment(lexer, valid_symbols, /* mark_end */ false, &multiline_comment_result);
            if (any_comment == STOP_PARSING_TOKEN_FOUND) {
                // This is a multiline comment. This scanner should be parsing those, so we might want to bail out and
                // emit it instead. However, we only want to do that if we haven't advanced through a _single_ line
                // comment on the way - otherwise that will get lumped into this.
                if (!has_seen_single_comment) {
                    lexer->mark_end(lexer);
                    *symbol_result = multiline_comment_result;
                    return STOP_PARSING_TOKEN_FOUND;
                }
            } else if (any_comment == STOP_PARSING_END_OF_FILE) {
                return STOP_PARSING_END_OF_FILE;
            } else if (any_comment == CONTINUE_PARSING_SLASH_CONSUMED) {
                // We accidentally ate a slash -- we should actually bail out, say we saw nothing, and let the next pass
                // take it from after the newline.
                return CONTINUE_PARSING_SLASH_CONSUMED;
            } else if (lexer->lookahead == '/') {
                // There wasn't a multiline comment, which we know means that the comment parser ate its `/` and then
                // bailed out. If it had seen anything comment-like after that first `/` it would have continued going
                // and eventually had a well-formed comment or an EOF. Thus, if we're currently looking at a `/`, it's
                // the second one of those and it means we have a single-line comment.
                has_seen_single_comment = true;
                while (lexer->lookahead != '\n' && lexer->lookahead != '\0') {
                    lexer->advance(lexer, true);
                }
            } else if (iswspace(lexer->lookahead)) {
                // We didn't see any type of comment - in fact, we saw an operator that we don't normally treat as an
                // operator. Still, this is a reason to stop parsing.
                return STOP_PARSING_NOTHING_FOUND;
            }

            // If we skipped through some comment, we're at whitespace now, so advance.
            while(iswspace(lexer->lookahead)) {
                any_comment = CONTINUE_PARSING_NOTHING_FOUND; // We're advancing, so clear out the comment
                lexer->advance(lexer, true);
            }
        }

        enum TokenType operator_result;
        bool saw_operator = eat_operators(
                                lexer,
                                valid_symbols,
                                /* mark_end */ false,
                                /* token_is_immediate */ false,
                                '\0',
                                &operator_result
                            );
        if (saw_operator) {
            // The operator we saw should suppress the newline, so bail out.
            return STOP_PARSING_NOTHING_FOUND;
        } else {
            // Promote the implicit newline to an explicit one so we don't check for operators again.
            *symbol_result = IMPLICIT_SEMI;
            ws_directive = STOP_PARSING_TOKEN_FOUND;
        }
    }

    // Let's consume operators that can live after a "semicolon" style newline. Before we do that, though, we want to
    // check for a set of characters that we do not consume, but that still suppress the semi.
    if (ws_directive == CONTINUE_PARSING_TOKEN_FOUND) {
        for (int i = 0; i < NON_CONSUMING_CROSS_SEMI_CHAR_COUNT; i++) {
            if (NON_CONSUMING_CROSS_SEMI_CHARS[i] == lookahead) {
                return CONTINUE_PARSING_NOTHING_FOUND;
            }
        }
    }

    if (semi_is_valid && ws_directive != CONTINUE_PARSING_NOTHING_FOUND) {
        // If the upcoming token is a compiler directive (`#if`/`#elseif`/`#else`/`#endif`) that is
        // valid in this parse state, prefer emitting the directive over an implicit semicolon. This
        // matters when a directive is the *first* member of a type body (e.g. a `#if` directly after
        // a `{`): there both a separator-style semi and the directive are valid, but the semi has no
        // slot in the grammar, so emitting it produces a spurious error. Suppressing the semi here
        // lets the directive be scanned instead. In a genuine separator position (e.g. between two
        // members) the directive tokens are not valid until the semi has been consumed, so this does
        // not interfere with using a newline as a member/statement separator.
        bool directive_is_valid = valid_symbols[DIRECTIVE_IF] || valid_symbols[DIRECTIVE_ELSEIF] ||
            valid_symbols[DIRECTIVE_ELSE] || valid_symbols[DIRECTIVE_ENDIF];
        if (lookahead == '#' && directive_is_valid) {
            return CONTINUE_PARSING_NOTHING_FOUND;
        }

        *symbol_result = lookahead == ';' ? EXPLICIT_SEMI : IMPLICIT_SEMI;
        return ws_directive;
    }

    return CONTINUE_PARSING_NOTHING_FOUND;
}

#define DIRECTIVE_COUNT 4
const char* DIRECTIVES[OPERATOR_COUNT] = {
    "if",
    "elseif",
    "else",
    "endif"
};

const enum TokenType DIRECTIVE_SYMBOLS[DIRECTIVE_COUNT] = {
    DIRECTIVE_IF,
    DIRECTIVE_ELSEIF,
    DIRECTIVE_ELSE,
    DIRECTIVE_ENDIF
};

static enum TokenType find_possible_compiler_directive(TSLexer *lexer) {
    bool possible_directives[DIRECTIVE_COUNT];
    for (int dir_idx = 0; dir_idx < DIRECTIVE_COUNT; dir_idx++) {
        possible_directives[dir_idx] = true;
    }

    int32_t str_idx = 0;
    int32_t full_match = -1;
    while(true) {
        for (int dir_idx = 0; dir_idx < DIRECTIVE_COUNT; dir_idx++) {
            if (!possible_directives[dir_idx]) {
                continue;
            }

            uint8_t expected_char = DIRECTIVES[dir_idx][str_idx];
            if (expected_char == '\0') {
                full_match = dir_idx;
                lexer->mark_end(lexer);
            }

            if (expected_char != lexer->lookahead) {
                possible_directives[dir_idx] = false;
                continue;
            }
        }

        uint8_t match_count = 0;
        for (int dir_idx = 0; dir_idx < DIRECTIVE_COUNT; dir_idx += 1) {
            if (possible_directives[dir_idx]) {
                match_count += 1;
            }
        }

        if (match_count == 0) {
            break;
        }

        lexer->advance(lexer, false);
        str_idx += 1;
    }

    if (full_match == -1) {
        // No compiler directive found, so just match the starting symbol
        return HASH_SYMBOL;
    }

    return DIRECTIVE_SYMBOLS[full_match];
}

static bool eat_raw_str_part(
    struct ScannerState *state,
    TSLexer *lexer,
    const bool *valid_symbols,
    enum TokenType *symbol_result
) {
    uint32_t hash_count = state->ongoing_raw_str_hash_count;
    if (!valid_symbols[RAW_STR_PART]) {
        return false;
    } else if (hash_count == 0) {
        // If this is a raw_str_part, it's the first one - look for hashes
        while (lexer->lookahead == '#') {
            hash_count += 1;
            advance(lexer);
        }

        if (hash_count == 0) {
            return false;
        }

        if (lexer->lookahead == '"') {
            advance(lexer);
        } else if (hash_count == 1) {
            lexer->mark_end(lexer);
            *symbol_result = find_possible_compiler_directive(lexer);
            return true;
        } else {
            return false;
        }

    } else if (valid_symbols[RAW_STR_CONTINUING_INDICATOR]) {
        // This is the end of an interpolation - now it's another raw_str_part. This is a synthetic
        // marker to tell us that the grammar just consumed a `(` symbol to close a raw
        // interpolation (since we don't want to fire on every `(` in existence). We don't have
        // anything to do except continue.
    } else {
        return false;
    }

    // We're in a state where anything other than `hash_count` hash symbols in a row should be eaten
    // and is part of a string.
    // The last character _before_ the hashes will tell us what happens next.
    // Matters are also complicated by the fact that we don't want to consume every character we
    // visit; if we see a `\#(`, for instance, with the appropriate number of hash symbols, we want
    // to end our parsing _before_ that sequence. This allows highlighting tools to treat that as a
    // separate token.
    while (lexer->lookahead != '\0') {
        uint8_t last_char = '\0';
        lexer->mark_end(lexer); // We always want to parse thru the start of the string so far
        // Advance through anything that isn't a hash symbol, because we want to count those.
        while (lexer->lookahead != '#' && lexer->lookahead != '\0') {
            last_char = lexer->lookahead;
            advance(lexer);
            if (last_char != '\\' || lexer->lookahead == '\\') {
                // Mark a new end, but only if we didn't just advance past a `\` symbol, since we
                // don't want to consume that. Exception: if this is a `\` that happens _right
                // after_ another `\`, we for some reason _do_ want to consume that, because
                // apparently that is parsed as a literal `\` followed by something escaped.
                lexer->mark_end(lexer);
            }
        }

        // We hit at least one hash - count them and see if they match.
        uint32_t current_hash_count = 0;
        while (lexer->lookahead == '#' && current_hash_count < hash_count) {
            current_hash_count += 1;
            advance(lexer);
        }

        // If we saw exactly the right number of hashes, one of three things is true:
        // 1. We're trying to interpolate into this string.
        // 2. The string just ended.
        // 3. This was just some hash characters doing nothing important.
        if (current_hash_count == hash_count) {
            if (last_char == '\\' && lexer->lookahead == '(') {
                // Interpolation case! Don't consume those chars; they get saved for grammar.js.
                *symbol_result = RAW_STR_PART;
                state->ongoing_raw_str_hash_count = hash_count;
                return true;
            } else if (last_char == '"') {
                // The string is finished! Mark the end here, on the very last hash symbol.
                lexer->mark_end(lexer);
                *symbol_result = RAW_STR_END_PART;
                state->ongoing_raw_str_hash_count = 0;
                return true;
            }
            // Nothing special happened - let the string continue.
        }
    }

    return false;
}

bool tree_sitter_swift_external_scanner_scan(
    void *payload,
    TSLexer *lexer,
    const bool *valid_symbols
) {
    // Figure out our scanner state
    struct ScannerState *state = (struct ScannerState *)payload;

    // Consume any whitespace at the start.
    bool token_is_immediate = !should_treat_as_wspace(lexer->lookahead);
    enum TokenType ws_result;
    enum ParseDirective ws_directive = eat_whitespace(lexer, valid_symbols, &ws_result);
    if (ws_directive == STOP_PARSING_TOKEN_FOUND) {
        lexer->result_symbol = ws_result;
        return true;
    }

    if (ws_directive == STOP_PARSING_NOTHING_FOUND || ws_directive == STOP_PARSING_END_OF_FILE) {
        return false;
    }

    bool has_ws_result = (ws_directive == CONTINUE_PARSING_TOKEN_FOUND);

    // Now consume comments (before custom operators so that those aren't treated as comments)
    enum TokenType comment_result;
    enum ParseDirective comment = ws_directive == CONTINUE_PARSING_SLASH_CONSUMED ? ws_directive : eat_comment(lexer, valid_symbols, /* mark_end */ true, &comment_result);
    if (comment == STOP_PARSING_TOKEN_FOUND) {
        lexer->mark_end(lexer);
        lexer->result_symbol = comment_result;
        return true;
    }

    if (comment == STOP_PARSING_END_OF_FILE) {
        return false;
    }
    // Now consume any operators that might cause our whitespace to be suppressed.
    enum TokenType operator_result;
    bool saw_operator = eat_operators(
                            lexer,
                            valid_symbols,
                            /* mark_end */ !has_ws_result,
                            token_is_immediate,
                            comment == CONTINUE_PARSING_SLASH_CONSUMED ? '/' : '\0',
                            &operator_result
                        );

    if (saw_operator && (!has_ws_result || is_cross_semi_token(operator_result))) {
        lexer->result_symbol = operator_result;
        if (has_ws_result) lexer->mark_end(lexer);
        return true;
    }

    if (has_ws_result) {
        // Don't `mark_end`, since we may have advanced through some operators.
        lexer->result_symbol = ws_result;
        return true;
    }

    // NOTE: this will consume any `#` characters it sees, even if it does not find a result. Keep
    // it at the end so that it doesn't interfere with special literals or selectors!
    enum TokenType raw_str_result;
    bool saw_raw_str_part = eat_raw_str_part(state, lexer, valid_symbols, &raw_str_result);
    if (saw_raw_str_part) {
        lexer->result_symbol = raw_str_result;
        return true;
    }

    return false;
}
